-- 156_replace_decision_139_2023_fintech_facilities_technology_infrastructure_information_systems_security_single_article_with_preamble_three_articles_attached_rules_and_three_annex_frameworks.sql
--
-- إعادة هيكلة قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم (139) لسنة 2023 بتاريخ 2023/6/21 بشأن التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين
-- اللازمة لاستخدام التكنولوجيا المالية لمزاولة الأنشطة المالية غير المصرفية (منشور بالوقائع المصرية العدد 150 تابع (أ) فى 11 يوليو 2023).
--
-- ===== الحالة السابقة (مراجعة الـ153 وثيقة، أولوية P2 - المجموعة أ) =====
-- مخزَّن بالهجرة 037 كمادة واحدة (article_no = 1، 65143 حرفاً) تحوى القرار كله (الديباجة والمواد الثلاث والقواعد المرفقة بقسميها والملاحق الثلاثة)، فلا يمكن الاستشهاد بمادة أو بند بعينه، ويتعذر
-- على الاسترجاع الدلالى أن يصل إلى بند بعينه داخل نص بهذا الحجم. والأهم أن المتن المخزَّن ليس نص الوقائع بل صياغة مختلفة عنه: قورن المخزَّن بالنص المنقول من الوقائع كلمة بكلمة بعد توحيد الهمزات والياء
-- والتاء المربوطة وحذف التشكيل وعلامات الترقيم، فظهر 246 فرقاً كلمياً، منها ثمانية فروق هيكلية فقط (عناوين المواد والأقسام والملاحق التى صارت عناوين مواد) والباقى فروق فى المتن، منها على سبيل المثال:
-- التعريف 1 مخزَّن "التجهيزات التحتية" بدل "التجهيزات"؛ التعريف 2 ترتيب بنوده مختلف ("اللازمة لنقل البيانات ووسائل التخزين ... وأجهزة الحاسبات وأجهزة الشبكات" بدل "أجهزة الشبكات ونقل البيانات ، وأجهزة الحاسبات
-- ووسائل التخزين ...") وسقط منه "وأنظمة البنية التحتية للتطبيقات"؛ التعريف 12 "فى الوفاء ... بالتعاملين" بدل "عن الوفاء ... للمتعاملين"؛ التعريف 13 "المعاملات المالية المرتبطة" بدل "المعاملات المرتبطة"؛ ثانياً/3 "حال فتح
-- الاتصال من التحقق عند الدخول" بدل "حال فتح الاتصال عند التحقق من الدخول"؛ ثانياً/4 "يعمل 24 ساعة" بدل "يعمل لمدة 24 ساعة"؛ وفى الملحق (1) "من خلال اجتماعات واستطلاعات" بدل "من خلال اجتماعات العملاء واستطلاعات" وسقوط "تقييم"
-- من "يتضمن ذلك تقييم ما إذا كانت جودة الخدمة ..."؛ وفى الملحق (2) سقوط "لإثبات فعاليتها فى معالجة ما قد تتعرض له الشركات والجهات المالية غير المصرفية من مخاطر التكنولوجيا" وتبديل "الرسالة" بـ"المهمة"؛ وفى الملحق (3)
-- "نفقات إدارة المخاطر السيبرانية" بدل "نفقات الأمن السيبرانى" و"الاستداد" بدل "الاسترداد" و"الوسائط" بدل "الوسائل". فالنص المخزَّن لا يصلح للاستشهاد الرسمى فى هذه المواضع.
--
-- ===== المصدر والمنهجية =====
-- PDF الوقائع المصرية (48 صفحة، ص 3-50 من العدد 150 تابع (أ)، صورة ممسوحة بلا طبقة نصية، قدّمه صاحب المشروع). لا طبقة نصية فاعتُمدت القراءة البصرية للصفحات الثمانى والأربعين كلها بدقة 200 نقطة/بوصة صفحةً
-- صفحة مع تكبير المواضع المشتبهة (الهمزات، "ى/ي"، التنوين، "مسئول/مسؤول"، الأرقام)، ثم قوبل النص المُدخَل بمخرجات OCR مستقلة (tesseract ara) كلمة بكلمة بعد تطبيع الهمزات والياء والأرقام الهندية: لم يبق فرق غير ضجيج المسح
-- (المصطلحات اللاتينية المشوهة وبعض الحروف) وترويسات الصفحات. الأرقام والمراجع القانونية مطابقة للمخزَّن ولما فى الصور (القانونان 5/2022 و151/2020، القرار 58/2022، جلسة 2023/6/21، 24 ساعة، 30 يوماً، خمس سنوات،
-- أعداد العمليات 40 و12 و62 و17 و102 فى الملحق 1، و12 و47 و11 و59 فى الملحق 2، و5 و23 و108 فى الملحق 3). أُبقى إملاء الوقائع ("ى" فى "فى" و"السيبرانى"، "ي" فى المواضع التى طُبعت بها كذلك
-- مثل "إدارة الأمن السيبراني" و"الاختبار الداخلي" و"التشغيل الحي"، "مسئول" و"مسؤول" كلتاهما كما طُبعتا، "الاجراءات" بلا همزة فى الملحق 3 (الاستجابة)، "ودراجات" و"فهم موظفو" و"بناءً الخدمات" كما هى)،
-- والتنوين كما فى الأصل (وفقًا، تنفيذًا، مضافا بلا تنوين)؛ الأرقام لاتينية؛ أُسقطت علامات التشكيل الصغيرة وأُبقى تنوين الفتح. أُبقى كذلك تقسيم الأصل لبند "استخدم العقود ... برنامج الأمن" إلى نقطتين
-- ("السيبرانى للشركة ..." نقطة مستقلة) كما طُبع. حُذفت ترويسة الصفحات ("الوقائع المصرية – العدد 150 تابع (أ) فى 11 يولية سنة 2023" وأرقام الصفحات)، وسطر "مجلس إدارة الهيئة العامة للرقابة المالية"
-- (جهة الإصدار) وعنوان القرار يوضع فى hierarchical_location للديباجة. التوقيع داخل المادة الثالثة. حد معلوم: همزة الألف فى بعض الكلمات ومواضع "ى/ي" لا تُحسم تماماً بدقة المسح وقد أُخذت بصورتها الأوضح؛
-- وهو فرق إملائى لا يمس المعنى.
--
-- ===== الهيكل =====
-- 20 صفاً، 20 نسخة (version_no = 1): ديباجة (article_no = 0) بثلاثة اطلاعات وموافقة المجلس، والمادة 1 (العمل بالقواعد المرفقة)، 2 (المتطلبات والمستندات)، 3 (النشر والتوقيع)، ثم 4 (أولاً - تعريفات: 20 تعريفاً) و5 (ثانياً - التجهيزات
-- والبنية التكنولوجية ووسائل الحماية: 5 بنود)، ثم الملاحق الثلاثة مقسمة بحسب أقسامها الأصلية لكبر حجمها (حتى نحو سبعة آلاف حرف للمادة): الملحق 1 (حوكمة تكنولوجيا المعلومات) = 6 مقدمة، 7 العمليات الاستراتيجية، 8 العمليات
-- التخطيطية الأساسية، 9 و10 العمليات التخطيطية المساندة (1-6 و7-12)؛ الملحق 2 (إدارة مخاطر التكنولوجيا) = 11 مقدمة، 12 العمليات الاستراتيجية، 13 تخطيطية المخاطر، 14 و15 تخطيطية الأنظمة وآليات التحكم (1-3 و4-7)؛ الملحق 3
-- (إدارة الأمن السيبرانى) = 16 مقدمة، 17 العمليات الاستراتيجية، 18 تخطيطية التحديد والحماية، 19 تخطيطية الرصد والاستجابة والاستعادة. لكل مادة عنوان وhierarchical_location يبيّن أنها من القواعد المرفقة بالقرار. المفتاح (1، 0) محفوظ
-- فلا تعيد بذرة 037 إدراج المادة القديمة (إدراج laws فيها ON CONFLICT DO NOTHING، وإدراج المادة مبنى على RETURNING فلا يعمل مع قانون موجود).
--
-- ===== التاريخ =====
-- effective_from = 2023-07-12: المادة 3 تعمل بالقرار "من اليوم التالى لتاريخ نشره"، ونشره بالوقائع المصرية العدد 150 تابع (أ) بتاريخ 2023/7/11 (ثابت بترويسة كل صفحة). لا تُمس بيانات laws.
--
-- ===== قابلية إعادة التشغيل =====
-- الحذف مشروط بألا تكون الحالة نظيفة (20 صفاً بديباجة سليمة والمادة 19 موجودة)؛ والإدراج ON CONFLICT DO NOTHING. تحقق الختام محصور فى هذا القرار ويفشل عند أى انحراف (عدد، بقايا ترويسة،
-- نص مخزَّن قديم، محتوى المواد، إجمالى الطول 65334 حرفاً).
--
-- ملاحظة تشغيلية: المواد الجديدة بلا embedding؛ يلزم scripts/backfill-embeddings.js بعد النشر.
BEGIN;
DO $fix156$
DECLARE
  v_law_id uuid;
  v_n int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[156] القرار 139/2023 غير موجود فى laws — تخطّى';
    RETURN;
  END IF;
  IF (SELECT count(*) FROM articles WHERE law_id = v_law_id) = 20
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND title = 'ديباجة القرار' AND body LIKE 'بعد الاطلاع%')
     AND EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 19 AND article_suffix_order = 0) THEN
    RAISE NOTICE '[156] القرار 139/2023 نظيف بالفعل — تخطّى الحذف';
  ELSE
    SELECT count(*) INTO v_n FROM articles WHERE law_id = v_law_id;
    DELETE FROM articles WHERE law_id = v_law_id;
    RAISE NOTICE '[156] أُزيلت % مادة من القرار 139/2023 (القرار كله فى مادة واحدة ومتنه صياغة مخالفة لنص الوقائع فى مواضع جوهرية)', v_n;
  END IF;
END
$fix156$;

