  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 0, 0, $h0$قرار مجلس إدارة الهيئة رقم 139 لسنة 2023 بتاريخ 2023/6/21 (منشور بالوقائع المصرية العدد 150 تابع (أ) فى 2023/7/11) بشأن التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين اللازمة لاستخدام التكنولوجيا المالية لمزاولة الأنشطة المالية غير المصرفية$h0$, $t0_0$ديباجة القرار$t0_0$, $b0_0$بعد الاطلاع على قانون تنظيم وتنمية استخدام التكنولوجيا المالية فى الأنشطة المالية غير المصرفية الصادر بالقانون رقم 5 لسنة 2022 ؛
وعلى قانون حماية البيانات الشخصية الصادر بالقانون رقم 151 لسنة 2020 ؛
وعلى قرار مجلس إدارة الهيئة العامة للرقابة المالية رقم 58 لسنة 2022 بشأن الشروط والإجراءات المتطلبة للتأسيس والترخيص والموافقة للشركات والجهات الراغبة فى مزاولة الأنشطة المالية غير المصرفية من خلال تقنيات التكنولوجيا المالية ؛
وعلى موافقة مجلس إدارة الهيئة بتاريخ 2023/6/21 ؛
قرر :$b0_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
