WITH ins4_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 4, 0, $h4$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - أولاً - تعريفات$h4$, $t4_0$القواعد المرفقة - أولاً - تعريفات$t4_0$, $b4_0$فى تطبيق أحكام القواعد الآتية يقصد بالمصطلحات التالية المعنى المبين قرين كل منها :
1- التجهيزات (Facilities Infrastructure) : البنية التحتية من مرافق وتجهيزات لازمة لمراكز المعلومات (الأساسية والبديلة) والتى تشمل التجهيزات اللازمة للوصول للمرافق العامة من الكهرباء والاتصالات والمياه والصرف ، والأنظمة الداخلية للكهرباء والتهوية والتبريد وكابلات الشبكات واكتشاف ومكافحة الحريق والأمن المادى والتحكم فى الدخول والمراقبة من خلال الدوائر التليفزيونية المغلقة .
2- البنية التكنولوجية (Technology Infrastructure) : البنية التحتية من أجهزة ونظم لازمة لمراكز المعلومات (الأساسية والبديلة) والتى تشمل أجهزة الشبكات ونقل البيانات ، وأجهزة الحاسبات ووسائل التخزين والأجهزة الطرفية المخصصة ، وأنظمة البنية التحتية للتطبيقات ، وأنظمة البنية التحتية لقواعد البيانات .
3- أنظمة المعلومات (Information Systems) : الأنظمة المكونة من تطبيقات (Applications) وقواعد بيانات (Databases) يتم تطويرها لتؤدى مهام محددة دعما لعمليات ودورات العمل المستهدفة ، وتساهم فى التنسيق بين المستخدمين الداخليين أو الخارجيين ، وقد تشمل تطبيقات "ذكاء اصطناعي" (Artificial Intelligence) لتوفير درجات أعلى من التشغيل الآلى (automation) والدقة والسرعة فى أداء المهام .
4- وسائل الحماية والتأمين (Protection & Security Mechanisms) : الآليات والمنهجيات المستخدمة لتوفير الآتى:
1- القدرة على منع وقوع المخاطر التكنولوجية (Technology Risk Prevention) التى من شأنها فقد الخصوصية والسرية (Confidentiality) ، أو السلامة والتكامل (Integrity) ، أو التوافر والإتاحة (Availability) ، للبنية التحتية للتجهيزات أو للبنية التحتية للبنية التكنولوجية أو لأنظمة المعلومات شاملة التطبيقات والبيانات .
2- القدرة على التحمل والمرونة للتعافى واستعادة الإمكانيات والوظائف والبيانات بعد وقوع المخاطر (After-Risk Recovery & Resiliency) .
5- المخاطر التكنولوجية (Technology Risk) : أى من التهديدات (Threats) أو نقاط الضعف (Vulnerabilities) الناشئة عن الاعتماد على البنية التكنولوجية وعلى أنظمة المعلومات فى أداء الأعمال والتى من شأنها حال وقوعها التأثير سلبًا على القدرة فى استمرار أداء تلك الأعمال .
6- مرونة التحمل التكنولوجية (Technology Resiliency) : قدرة البنية التكنولوجية وأنظمة المعلومات على التحمل واستعادة الإمكانات والوظائف المستهدفة بعد وقوع خطر تكنولوجى .
7- المخاطر السيبرانية (Cyber Risk) : أى من التهديدات (Threats) أو نقاط الضعف (Vulnerabilities) الناشئة عن اتصال البنية التحتية للتكنولوجيا الداخلية بالشبكات الخارجية أو الشبكة العالمية للتواصل (الإنترنت) .
8- مرونة التحمل السيبرانية (Cyber Resiliency) : قدرة البنية التكنولوجية وأنظمة المعلومات على التحمل واستعادة الإمكانات والوظائف المستهدفة بعد وقوع خطر سيبرانى .
9- أمن البيانات (الأمن السيبراني) فى مزاولة الأنشطة المالية غير المصرفية (NBFS-Cybersecurity) : إجراءات وعمليات تقنية وتنظيمية من شأنها الحفاظ على خصوصية البيانات وسريتها وسلامتها ووحدتها وتكاملها فيما بينها .
10- المنصة الرقمية المستخدمة فى مزاولة الأنشطة المالية غير المصرفية (NBFS-Digital Platform) : نموذج أعمال قائم على استخدام الوسائل التكنولوجية فى مزاولة الأنشطة المالية غير المصرفية وفى عرض المنتجات والخدمات المرتبطة بها على الأشخاص الراغبين فى الحصول عليها ، ويسمح بتبادل البيانات والمعلومات اللازمة لإتمام هذه التعاملات .
11- الجهات الراغبة فى تقديم خدمات التعهيد (Outsourcing Technology Service Provider) : جهة تقدم خدمات تكنولوجية عن طريق اتفاقية تعهيد (Outsourcing Agreement) يكون الطرف العاهد (Outsourcing Party) هو المستفيد من الخدمة ويكون الطرف المعهد إليه (Outsourcee) هو مقدم الخدمة .
12- أنظمة التكنولوجيا الحرجة (NB-Critical-System) : نظام أو تطبيق يؤدى فشله إلى إضعاف قدرة الشركات والجهات العاملة فى الأنشطة المالية غير المصرفية عن الوفاء بالتزاماتها للمتعاملين أو للهيئة العامة للرقابة المالية .
13- بيانات العميل (Client Data) : بيانات تتعلق بالعميل أو حساباته أو الحسابات المرتبطة بالمنتجات المالية غير المصرفية أو المعاملات المرتبطة بتلك المنتجات المالية غير المصرفية .
14- معلومات التعرف الشخصية (Personally Identifiable Information) : أى بيانات للعميل يمكن استخدامها لتمييز أو تتبع هوية الشخص .
15- الإدارة التنفيذية للشركة (Executive Management) : وتشمل الوحدات التنظيمية المسئولة عن العمليات التخطيطية على المستوى التنفيذى (Planning Processes – Executive Level) ، والإشراف والرقابة الداخلية على الإجراءات التطبيقية على المستوى التشغيلى (Internal Auditing on Applied Procedures – Operational Level) لوظائف وخدمات أعمال الأنشطة المالية غير المصرفية أو لوظائف وخدمات تكنولوجيا المعلومات الممكنة .
16- الإدارة التشغيلية للشركة (Operational Management) : وتشمل الوحدات التنظيمية المسئولة عن الإجراءات التطبيقية على المستوى التشغيلى (Applied Procedures – Operational Level) ، لوظائف وخدمات أعمال الأنشطة المالية غير المصرفية أو لوظائف وخدمات تكنولوجيا المعلومات الممكنة .
17- العمليات الاستراتيجية (Strategy Processes) : وتشمل العمليات (Processes) المحققة لاستراتيجية مستهدفة من خلال دورة حياة معينة (Intended Life Cycle) ، وتكون لكل عملية مجموعة من المدخلات (Inputs) ومجموعة من المخرجات (Outputs) ، وعلى أن تكون المخرجات من كل عملية من العمليات مدخلات لعملية أخرى (أو لعمليات أخريات) ، ويكون للمجموعة خصائص الدورية والتكرار (Cyclical Iterations) وعلى أن يتحقق من دورة حياة العمليات الاستراتيجية "أغراض وقيم مضافة" (Purpose & Value-add) تتطور مع كل تكرار للدورة . وتمثل "العمليات الاستراتيجية" المستوى الاستراتيجى لإطار العمل المستهدف (Intended Framework) .
18- العمليات التخطيطية (Planning Processes) : وتشمل مجموعة العمليات (Processes) المحققة لخطط مستهدفة ، تنفيذًا لاستراتيجية معينة ، وتكون لكل عملية مجموعة من المدخلات (Inputs) ومجموعة من المخرجات (Outputs) ، وعلى أن تكون المخرجات من كل عملية من العمليات مدخلات لعملية أخرى (أو لعمليات أخريات) ، وعلى أن يتحقق من مجموعة العمليات التخطيطية "الأغراض والقيم المضافة" للاستراتيجية المعينة . وتمثل "العمليات التخطيطية" المستوى التنفيذى لإطار العمل المستهدف (Intended Framework) .
19- الإجراءات التطبيقية (Applied Procedures) : مجموعة الإجراءات (Procedures) المطبقة لعمليات تخطيطية معينة ، ويكون لكل إجراء "حادث مشغل" (trigger events) كما يكون له "حالات ناتجة" (resulting state) والتى قد تكون "مشغلة" لإجراء آخر أو لإجراءات أخرى ، وعلى أن يتحقق من مجموعة الإجراءات التطبيقية "الأغراض والقيم المضافة" للعمليات التخطيطية المعينة . وتمثل الإجراءات التطبيقية "المستوى التشغيلي" لإطار العمل المستهدف (Intended Framework) .
20- الجهات المخاطبة :
• الشركات الراغبة فى الحصول على ترخيص لمزاولة الأنشطة المالية غير المصرفية من خلال تقنيات التكنولوجيا المالية تحت مظلة القانون رقم 5 لسنة 2022
• الشركات والجهات الحاصلة على ترخيص من الهيئة بمزاولة أى من الأنشطة المالية غير المصرفية تحت مظلة قوانين أخرى ، والراغبة فى الحصول على موافقة الهيئة لتباشر هذه الأنشطة باستخدام بعض مجالات التكنولوجيا المالية بنفسها ، أو من خلال إحدى جهات التعهيد تحت مظلة القانون رقم 5 لسنة 2022
• الشركات الراغبة فى تقديم خدمات التعهيد فى مجالات التكنولوجيا المالية التى يمكن استخدامها فى مزاولة الأنشطة المالية غير المصرفية تحت مظلة القانون رقم 5 لسنة 2022$b4_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins4_0;

WITH ins5_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 5, 0, $h5$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ثانياً - التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين$h5$, $t5_0$القواعد المرفقة - ثانياً - التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين$t5_0$, $b5_0$1- تلتزم الشركات والجهات المخاطبة بأحكام هذا القرار بتوفير التجهيزات التى تحددها الهيئة واللازمة للربط الآلى معها .
2- تلتزم الشركات والجهات المخاطبة بأحكام هذا القرار بتوفير أجهزة الخوادم الأساسية التالية كحد أدنى لمتطلبات البنية التكنولوجية وأنظمة المعلومات :
• حاسبات تعمل كخوادم لقواعد البيانات Database Servers .
• حاسبات تعمل كخوادم للتطبيقات Application Servers .
• حاسبات تعمل كخوادم للويب Web Server .
على أن يتم مراعاة التالى :
• توفير نظم تشغيل حديثة ومرخصة .
• توفير الأنظمة والتطبيقات والبرمجيات – المرخصة – اللازمة لتشغيل الخدمات المختلفة .
• الإتاحة الدائمة للخدمات دون توقف (High Availability) .
3- تلتزم الشركات والجهات المخاطبة بأحكام هذا القرار بضوابط أمن المعلومات التالية كحد أدنى :
• نظام جدار نارى (Next Generation Firewall) لتأمين الشبكات والمعلومات .
• نظام حماية لأنظمة الويب (Web Application Firewall) .
• نظم أمن المعلومات لكافة الأصول .
• نظام رصد ومراقبة كافة الأحداث المرتبطة بالأصول بما يتيح الرصد اللحظى وإصدار التقارير المجمعة للأحداث المرتبطة .
• استخدام خاصية تشفير البيانات بما يتوافق مع المعايير العالمية فى تشفير قواعد البيانات .
• إجراء الصيانة الدورية للأجهزة والأنظمة وتأمين الشبكات والمعلومات مع مراعاة قواعد الضبط المناسبة لها وتحديثها بصفة مستمرة .
• تزويد جميع أجهزة الحاسب المتصلة بشبكة الشركة (حاسبات مكتبية ، محمولة ، خوادم) ببرامج محدثة ومرخصة لمكافحة الفيروسات والبرمجيات الضارة مثل نظام (Antivirus) ونظام (Endpoint Detection & Response) .
• عمل التحديث الدورى لأنظمة التشغيل والتطبيقات والبرمجيات المختلفة .
• الفصل المؤمن (Security Isolation) بين أنظمة الخدمات المختلفة وفقا للمستوى الأمنى لها .
• عمل اختبارات معتمدة (Penetration Test) لقياس مدى تأمين الشبكات والتطبيقات والبرمجيات مرة واحدة سنويًا على الأقل وتسليم نسخة من هذه الاختبارات للهيئة ، ويجوز للهيئة طلب إعادة الاختبارات إذا تبين وجود نقاط ضعف تستدعى ذلك .
• إبلاغ الهيئة عند حدوث اختراقات لأمن المعلومات (Security Incidents) التى تحدث على مستوى البنية الأساسية للمعلومات والأنظمة العاملة عليها .
• تأمين الموقع الإلكترونى بشهادة تأمين إلكترونية سارية مخصصة للتعريف وتشفير البيانات (SSL Certificate) ، بحيث تظهر للعملاء عند تصفحهم الموقع الالكترونى بشهادة تأمين الكترونية .
• إصدار رقم فريد (Unique Session ID) ، مضافا إليه ختم التوقيت (Time Stamp) لكل اتصال حال فتح الاتصال عند التحقق من الدخول .
• تسجيل الأنشطة (Logging Activities) التى تحدث على جميع الأجهزة والأنظمة مثل (System Logs, Security Logs, Application Logs) وما تعتمد عليه من أجهزة مساعدة مثل (الحاسبات ، وأجهزة شبكات ، وأجهزة تأمين معلومات) لمدة لا تقل عن خمس سنوات من تاريخ حدوث النشاط .
• الاحتفاظ بسجلات التعاملات على الحساب كاملة (Transactions Logs) بما فى ذلك جميع عمليات تسجيل الدخول والخروج وغيرها لمده لا تقل عن خمس سنوات .
4- تلتزم الشركات والجهات المخاطبة بأحكام هذا القرار بالضوابط التالية :
• أن تكون قاعدة بيانات عملاء الشركة داخل الحدود الجغرافية لجمهورية مصر العربية .
• إبلاغ الهيئة فى حالة اتخاذ أى إجراءات لنقل مقرها أو مركز بياناتها (Data Center) بمدة لا تزيد على 30 يومًا من تاريخ البدء فى اتخاذ الإجراءات .
• توفير مركز لخدمة العملاء يعمل لمدة 24 ساعة يوميا للرد على استفسارات العملاء وحل المشاكل محل الاستفسار فور حدوثها .
• توقيع اتفاقية مستوى الخدمات (Service Level Agreement) بين كل من الشركة وعملائها .
5- تعتبر الأطر العامة (إطار عمل حوكمة تكنولوجيا المعلومات وإطار عمل إدارة مخاطر التكنولوجيا وإطار عمل إدارة الأمن السيبراني) الواردة بالملاحق المرفقة أدلة استرشادية للممارسات الصحيحة ، وتحدد الهيئة الحد الأدنى اللازم اتباعه منها فى كل حالة على حدة .$b5_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins5_0;

WITH ins6_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 6, 0, $h6$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (1) - إطار عمل حوكمة تكنولوجيا المعلومات (ITG-F)$h6$, $t6_0$ملحق (1) - إطار عمل حوكمة تكنولوجيا المعلومات (ITG-F)$t6_0$, $b6_0$يقصد بالمصطلحات التالية المعنى المبين قرين كل منها :
إطار عمل حوكمة تكنولوجيا المعلومات : هو عنصر أساسى ومتمم لحوكمة المؤسسات ، وما يستتبعه من حوكمة لإدارة خدمات تكنولوجيا المعلومات (ITSM : Information Technology Service Management) . ويتكون إطار العمل من العمليات الاستراتيجية على المستوى الاستراتيجى ، والعمليات التخطيطية على المستوى التنفيذى ، والإجراءات التطبيقية على المستوى التشغيلى ، ويتبنى هذا العرض لإطار عمل "حوكمة تكنولوجيا المعلومات" منهجية التوجه الخدمى لتقديم خدمات تكنولوجيا المعلومات (ITSM) لكل من التجهيزات ، والبنية التكنولوجية ، وأنظمة معلومات ، ووسائل الحماية والتأمين ، ويجوز استخدام أفضل الممارسات وأطر العمل العالمية الأخرى ، أو تبنى إطار عمل بديل بعد العرض والموافقة من الهيئة .
ويجب على مجلس إدارة الشركة وضع واعتماد "استراتيجية تكنولوجيا المعلومات" ويكون ذلك من خلال "إطار عمل حوكمة تكنولوجيا المعلومات" والذى يكون معتمدًا من مجلس الإدارة وحاكمًا للإدارة التنفيذية وللإدارة التشغيلية . كما يجب على مجلس الإدارة أيضًا مراجعته بشكل دورى ، مرة واحدة على الأقل كل ثلاث سنوات ، ويكون لمجلس الإدارة تشكيل لجنة تسمى "لجنة حوكمة تكنولوجيا المعلومات" التابعة لمجلس الإدارة وتكون مسئولة عن الإشراف على تنفيذ إطار عمل حوكمة خدمات تكنولوجيا المعلومات والتأكد من ملائمة دورة العمل والمسئولين عن تنفيذها ، والتأكد من الالتزام بالإجراءات المطلوب اتباعها .
ويشمل إطار عمل تكنولوجيا المعلومات خمس عمليات استراتيجية أساسية لدورة الحياة (LP) ، تتضمن 40 عملية تخطيطية على المستوى التنفيذى ، بالإضافة إلى 12 عملية استراتيجية مساندة لدورة الحياة (SP) ، تتضمن 62 عملية تخطيطية على المستوى التنفيذى ، بإجمالى 17 عملية استراتيجية و102 عملية تخطيطية .$b6_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins6_0;

WITH ins7_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 7, 0, $h7$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (1) - العمليات الاستراتيجية$h7$, $t7_0$ملحق (1) - العمليات الاستراتيجية$t7_0$, $b7_0$1- العمليات الاستراتيجية : هى العمليات التى تهدف إلى تحويل موارد مقدم خدمات تكنولوجيا المعلومات إلى خدمات ذات قيمة للعملاء ، ويجب توفير هذه الخدمات بمستويات متفق عليها من الجودة والتكلفة والمخاطر ، وتنقسم إلى :
أولاً - العمليات الاستراتيجية الأساسية لدورة الحياة ، وتشمل :
1- تحديد الاتجاه الاستراتيجى : ويقصد به اتخاذ قرارات استراتيجية لخدمة العملاء باستخدام تكنولوجيا المعلومات ، بدءًا من تقييم احتياجات العملاء وبيئة الأعمال ، وتشمل تحديد الخدمات التى يجب أن تقدم والقدرات المطلوبة لتقديمها .
2- تصميم الخدمات الجديدة أو المعدلة : ويقصد به تحديد النتائج المتوقعة والخصائص المطلوبة لخدمة جديدة أو معدلة ، وتحديد البنية التحتية والقدرات الأخرى اللازمة لتقديم الخدمة ، وتطوير نهج تنفيذها .
3- بناء الخدمات الجديدة أو المعدلة : ويقصد به بناء ونشر خدمات جديدة أو معدلة ، ويشمل تنسيق تطوير واقتناء واختبار جميع مكونات الخدمة المطلوبة .
4- تشغيل الخدمات : ويقصد به ضمان تقديم الخدمات بفعالية وكفاءة ، بما يتماشى مع الالتزامات التعاقدية ، ويشمل تلبية طلبات الخدمة ، وحل الحوادث والمشكلات ، وكذلك تنفيذ المهام التشغيلية الروتينية .
5- تحسين الخدمات : ويقصد به التحقق باستمرار مما إذا كانت الخدمات تقدم النتائج المطلوبة ، وتحديد إمكانات التحسين فى طريقة إنتاج الخدمات .
ثانيًا - العمليات الاستراتيجية المساندة لدورة الحياة ، وتشمل :
1- إعداد وصيانة نظام إدارة الخدمة : ويقصد به إنشاء نظام إدارة الخدمة وتشغيله وتحسينه باستمرار ، وتكون هذه العملية مسئولة عن إدارة سياسات وعمليات إدارة الخدمة كمكونات رئيسية فى نظام إدارة الخدمة .
2- الحفاظ على محفظة الخدمات : ويقصد به ضمان احتواء محفظة الخدمات على معلومات متسقة ومحدثة حول الخدمات التى يديرها مقدم الخدمة ، ويتحقق ذلك من خلال التحكم فى التغييرات فى محفظة الخدمات وتعريفات الخدمة ، بالإضافة إلى إجراء مراجعات منتظمة لمحفظة الخدمات .
3- إدارة علاقات العملاء : وتكون هذه العملية مسئولة عن الحفاظ على علاقة إيجابية مع العملاء ، وتحديد العملاء الجدد المحتملين ، وضمان الحصول على تعليقات منتظمة من العملاء الحاليين من خلال اجتماعات العملاء واستطلاعات الرأى ، وتوقيع اتفاقيات خدمة العملاء مع عملاء مقدم الخدمة .
4- إدارة معلومات مكونات التهيئة : ويقصد بها الاحتفاظ بمعلومات حول عناصر مكونات التهيئة المطلوبة لتقديم الخدمات ، بما فى ذلك العلاقات بينهم .
5- تقييم التغييرات والتنسيق لها : ويقصد به التحكم فى دورة حياة جميع التغييرات ويكون غرضها الرئيسى هو التمكين من إجراء تغييرات مفيدة ، مع الحد الأدنى من تعطيل الخدمات .
6- إدارة المشاريع : ويقصد به تخطيط وتنسيق الموارد لإكمال مشروع فى الوقت والتكلفة والنطاق المستهدفين .
7- ضمان الأمن : ويقصد به ضمان أمن مجموعة خدمات مقدم الخدمة ، ومواءمة الاحتياجات الأمنية لمقدم الخدمة مع احتياجات عملائه ، وضمان حماية الأنظمة والبيانات من التطفل ، وألا يتم الوصول إليها إلا من قبل الأطراف المصرح لها .
8- الاستعداد لأحداث الكوارث : ويقصد به التأكد من أن مقدم الخدمة يمكنه توفير الحد الأدنى من مستويات الخدمة المتفق عليها فى حالة الأحداث التى تعتبر كوارث ، ويتم تحقيق ذلك فى المقام الأول من خلال تنفيذ آليات لمنع حدوث الكوارث ، ومن خلال وضع خطط وترتيبات الاستمرارية لاستعادة الخدمات بمجرد وقوع كارثة .
9- ضمان الامتثال : ويقصد به ضمان امتثال الخدمات والعمليات والأنظمة للمتطلبات القانونية ذات الصلة والمعايير وسياسات المؤسسة .
10- إدارة الموارد البشرية : ويقصد به توفير المهارات ومستويات الموظفين المطلوبة من قبل مقدم الخدمة لتحقيق أهدافه .
11- إدارة الموردين : ويقصد به التأكد من أن جميع الاتفاقيات مع الموردين تدعم احتياجات العمل ، وأن جميع الموردين يفون بالتزاماتهم التعاقدية .
12- إدارة الشئون المالية للخدمة : ويقصد به إدارة متطلبات الميزانية والمحاسبة والرسوم الخاصة بمقدم الخدمة .$b7_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins7_0;

WITH ins8_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 8, 0, $h8$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (1) - العمليات التخطيطية الأساسية لدورة الحياة$h8$, $t8_0$ملحق (1) - العمليات التخطيطية الأساسية لدورة الحياة$t8_0$, $b8_0$2- العمليات التخطيطية ، وتشمل :
أولاً - العمليات التخطيطية الأساسية لدورة الحياة ، وتشمل :
1- تحديد الاتجاه الاستراتيجى :
• تقييم الوضع الاستراتيجى الحالى : ويقصد به تقييم الوضع القائم لمقدم خدمات تكنولوجيا المعلومات والقدرات اللازمة لأدائها ، واحتياجات عملائها ، والبدائل المتاحة لتلك الخدمات ومكوناتها .
• تحديد توجيهات الاستخدام الاستراتيجى للتكنولوجيا : ويقصد به الموائمة مع الأهداف الاستراتيجية للأعمال .
• تحديد المبادرات الاستراتيجية : ويقصد به دراسة وتحديد المبادرات وأنسب الطرق لتنفيذها .
• البدء فى مشروعات تطوير الخدمات : ويقصد به تحديد مسئول الخدمة وتحديد وضمان الموازنة اللازمة ، وتحديد جدول زمنى .
• مراقبة المبادرات الاستراتيجية : ويقصد به التحقق من سيرها وفقًا للمخطط ، واتخاذ تدابير تصحيحية عند الضرورة .
2- تصميم الخدمات الجديدة أو المعدلة :
• تحديد خصائص الخدمة المطلوبة : ويقصد به تحديد النتيجة المتوقعة والخصائص المطلوبة لخدمة جديدة أو معدلة ، ويتضمن ذلك تحديد خصائص أى خدمات داعمة يجب إعدادها أو تعديلها حتى تتمكن من تقديم الخدمة الجديدة .
• تصميم البنية التحتية المطلوبة : ويقصد به تحديد البنية التحتية المطلوبة والإمكانات الأخرى التى يجب إنشاؤها قبل تقديم خدمة جديدة أو معدلة .
• تحديد منهجية التنفيذ : ويقصد به وصف كيفية إنشاء البنية التحتية والقدرات الأخرى المطلوبة لتقديم خدمة جديدة أو معدلة .
• الإعداد لتنفيذ الخدمة : ويقصد به تقديم مستندات تصميم الخدمة للمراجعة النهائية وتحديد ما إذا كانت الخدمة جاهزة للتنفيذ .
3- بناءً الخدمات الجديدة أو المعدلة :
• التنسيق بين عمليات التطوير والشراء : ويقصد به بدء وتنسيق الأنشطة لتطوير أو شراء مكونات البنية التحتية والقدرات الأخرى المطلوبة لخدمة جديدة أو متغيرة .
• تطوير التطبيقات والأنظمة : ويقصد به تطوير أو تهيئة مكونات التطبيقات والأنظمة التى توفر الوظائف المطلوبة للخدمات ، وتتضمن هذه العملية تطوير تطبيقات وأنظمة مخصصة بالإضافة إلى تخصيص وتهيئة مكونات المنتجات التى تم شرائها .
• قبول تسليم مكونات الخدمة : ويقصد به تلقى مكونات الخدمة المطلوبة وتقديمها للتقييم الأولى ، وتضمن هذه العملية أن المكونات التى تفى بمعايير الجودة الصارمة فقط هى التى يسمح لها بالدخول إلى مرحلة اختبار الخدمة الرئيسية .
• إنشاء أو تحديث الوثائق التشغيلية : ويقصد به تقديم إرشادات لتشغيل الخدمة الجديدة .
• اختبار مكونات الخدمة : ويقصد به اختبار جميع مكونات الخدمة وكذلك جميع الأدوات والآليات المطلوبة للنشر ، وتضمن هذه العملية نشر المكونات التى تلبى معايير الجودة الصارمة فقط فى البيئة الإنتاجية الحية .
• نشر مكونات الخدمة فى البيئة الإنتاجية : ويقصد به نشر مكونات الخدمة فى بيئة الإنتاج الحية .
• الإعداد لتفعيل الخدمة : ويقصد به تقييم ما إذا كانت جميع مكونات البنية التحتية والقدرات الأخرى موجودة قبل السماح بتفعيل الخدمات الجديدة .
4- تشغيل الخدمات :
• دعم عملية تشغيل الخدمة : ويقصد به تقديم الدعم لعملية الخدمة ، من خلال ضمان توفر الموارد المطلوبة لتشغيل الخدمات ، وعن طريق تكوين وصيانة أنظمة الدعم التشغيلى ، وغيرها .
• تنظيم عملية الخدمة : ويقصد به تقديم إرشادات للإجراءات التى سيتم تنفيذها بواسطة طاقم التشغيل .
• مراقبة الخدمات : ويقصد به التأكد من مراقبة البنية التحتية للخدمة واستخدام الخدمة باستمرار ، ولتحديد الاستجابات المناسبة إذا تم اكتشاف أى مخالفات .
• إصدار تقارير جودة الخدمة : ويقصد به قياس جودة الخدمة المحققة على أساس منتظم وتحديد المجالات التى يجب تحسين جودة الخدمة فيها .
• أداء المهام التشغيلية الروتينية : ويقصد به تنفيذ المهام التشغيلية الروتينية المطلوبة لتقديم جودة الخدمة المتفق عليها على أساس مستدام .
• حل الحوادث وطلبات الخدمة : ويقصد بحل حوادث وطلبات الخدمة هو إعادة الخدمة إلى المستخدمين فى أسرع وقت ممكن .
• دعم حل الحوادث وطلبات الخدمة : ويقصد به تقديم الدعم لحل الحوادث وطلبات الخدمة ، على سبيل المثال عن طريق تكوين الأنظمة لإدارة الحوادث وطلبات الخدمة ، وعن طريق الحفاظ على مجموعة من نماذج طلب الخدمة والحوادث .
• تسجيل الحوادث وطلبات الخدمة : ويقصد به تسجيل جميع التفاصيل ذات الصلة بالحوادث وطلبات الخدمة ، والتحقق من إعطاء جميع التراخيص المطلوبة ، وتحديد أولويات الحوادث أو الطلبات .
• تلبية طلبات الخدمة : وتكون عادة إما طلبات للحصول على معلومات أو طلبات لتنفيذ تغييرات طفيفة (قياسية) مثل إعادة تعيين كلمة المرور .
• إبلاغ المستخدمين والعملاء بشكل استباقى : ويقصد به إبلاغ المستخدمين بإخفاقات الخدمة الفعلية أو الوشيكة بمجرد أن تصبح معروفة لدعم المستوى الأول ، بحيث يكون المستخدمون والعملاء فى وضع يمكنهم من التكيف مع الانقطاعات ، وتكون هذه العملية مسؤولة أيضًا عن توزيع معلومات مهمة أخرى ، مثل تنبيهات الأمان الحالية .
• حل الحوادث الكبرى : ويقصد به حل حادث كبير يتسبب فى انقطاعات خطيرة فى الأنشطة التجارية ويجب حلها على وجه السرعة ، بهدف استرداد سريع للخدمة ، ربما عن طريق حل بديل .
• حل الحوادث فى دعم المستوى الأول : ويقصد به حل حادث (انقطاع الخدمة) ضمن الإطار الزمنى المتفق عليه ، ويهدف إلى الاسترداد السريع للخدمة ، ربما من خلال تطبيق حل بديل ، وبمجرد أن يتضح أن دعم المستوى الأول غير قادر على حل الحادث نفسه أو عندما يتم تجاوز الأوقات المستهدفة لحل المستوى الأول ، يتم نقل الحادث إلى دعم المستوى الثانى .
• حل الحوادث فى المستوى الثانى : ويقصد به لحل حادث (انقطاع الخدمة) ضمن الإطار الزمنى المتفق عليه ، ويهدف إلى استرداد سريع للخدمة ، ربما عن طريق حل بديل ، وإذا لزم الأمر ، قد تشارك مجموعات دعم متخصصة فى هذا الشأن .
• مراقبة الحوادث وطلبات الخدمة : ويقصد به المراقبة المستمرة لحالة معالجة الحوادث المعلقة وطلبات الخدمة ، بحيث يمكن التصعيد واتخاذ التدابير المضادة إذا كان من المحتمل انتهاك أوقات الحل المتفق عليها .
• إغلاق الحوادث وطلبات الخدمة : ويقصد به تقديم سجلات طلب الخدمة والحادث إلى رقابة الجودة النهائية قبل الإغلاق الرسمى . ويهدف إلى التأكد من أن تاريخ حل الحادث أو طلب الخدمة موصوف بتفاصيل كافية ، ويجب تسجيل النتائج المستخلصة من حل الحوادث لاستخدامها فى المستقبل .
• حل المشكلات : ويقصد به إدارة دورة حياة جميع المشكلات ، حيث تكون المشكلة هى السبب الكامن وراء واحد أو عدة حوادث (محتملة) . وتهدف هذه العملية إلى منع وقوع حوادث الخدمة ، وتقليل تأثير الحوادث التى لا يمكن منعها .
• تحديد المشكلات بشكل استباقى : ويقصد به تحسين التوافر العام للخدمات من خلال تحديد المشكلات بشكل استباقى ، وتهدف هذه العملية إلى تحديد المشكلات وحلها أو توفير حلول بديلة مناسبة قبل حدوث مزيد من حوادث الخدمة .
• تصنيف المشكلات وترتيبها حسب الأولوية : ويقصد به تسجيل المشاكل وترتيبها حسب الأولوية مع العناية المناسبة ، من أجل تسهيل حل سريع وفعال .
• تحليل المشكلات وحلها : ويقصد به تحديد الأسباب الكامنة وراء المشكلات وتحديد أنسب حل للمشكلات وتوفير حل مؤقت إذا لم يتوفر حل كامل .
• مراقبة المشكلات المعلقة : ويقصد به المراقبة المستمرة للمشكلات المعلقة فيما يتعلق بحالة المعالجة الخاصة بها ، واتخاذ الإجراءات التصحيحية كما هو مطلوب .
• إغلاق المشاكل : ويقصد به التأكد من أن حل المشكلة كان ناجحًا وأن جميع المعلومات ذات الصلة محدثة .
5- تحسين الخدمات :
• أداء مراجعات الخدمة : ويقصد به تحديد إمكانيات تحسين الخدمة ، يتضمن ذلك تقييم ما إذا كانت جودة الخدمة المقدمة تتماشى مع الالتزامات التعاقدية ، وكذلك اكتشاف نقاط الضعف فى طريقة تقديم الخدمة .
• تحديد تحسينات الخدمة : ويقصد به تحديد أهداف مبادرات تحسين الخدمة ونهج تنفيذها ، وهذا يشمل إعداد دراسات الجدوى للمبادرات .
• بدء مبادرات تحسين الخدمة : ويقصد به إطلاق مبادرات تحسين الخدمة ، ويتضمن ذلك الحصول على إذن من خلال طلب ميزانية وتقديم طلب للتغيير .
• تنفيذ تحسينات الخدمة : ويقصد به تنفيذ واختبار ونشر تحسينات الخدمة ، ويتضمن ذلك تحديث تعريفات واتفاقيات الخدمة ذات الصلة .
• مراقبة مبادرات تحسين الخدمة : ويقصد به تقييم ما إذا كانت مبادرات تحسين الخدمة تسير وفقًا للخطة ، وإدخال تدابير تصحيحية عند الضرورة .$b8_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins8_0;

WITH ins9_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 9, 0, $h9$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (1) - العمليات التخطيطية المساندة لدورة الحياة (1 إلى 6)$h9$, $t9_0$ملحق (1) - العمليات التخطيطية المساندة لدورة الحياة (1 إلى 6)$t9_0$, $b9_0$ثانيًا - العمليات التخطيطية المساندة لدورة الحياة ، وتشمل :
1- إعداد وصيانة نظام إدارة الخدمة :
• تحديد تحسينات العملية : ويقصد به تحديد أهداف مبادرات تحسين العملية والنهج المتبع فى تنفيذها ، ويشمل إعداد دراسات الجدوى للمبادرات .
• بدء مبادرات تحسين العملية : ويقصد به إطلاق مبادرات تحسين العملية ، ويتضمن ذلك الحصول على إذن من خلال طلب ميزانية وتقديم طلب للتغيير .
• عمليات التصميم والسياسات : ويقصد به إنتاج تصميمات جديدة أو محدثة لعمليات إدارة الخدمة ، والتى يتم تنفيذها عادةً من خلال مبادرات تحسين العملية أو كجزء من مشاريع تطوير الخدمة .
• تنفيذ تحسينات العملية : ويقصد به تنفيذ واختبار ونشر عمليات إدارة خدمة جديدة أو تحسينات على العمليات الحالية ، وهذا يشمل تحديث وثائق العملية ذات الصلة .
• مراقبة مبادرات تحسين العملية : ويقصد به تقييم ما إذا كانت مبادرات تحسين العملية تسير وفقًا للخطة ، وإدخال تدابير تصحيحية عند الضرورة .
• تشغيل العمليات : ويقصد به ضمان تشغيل العمليات بفعالية وكفاءة ، بما يتماشى مع أهداف مقدم الخدمة ، ويتضمن ذلك إدارة الموارد اللازمة لتشغيل العملية ، بالإضافة إلى إعداد التقارير عن أداء العملية .
• أداء مراجعات العملية : ويقصد به تقديم عمليات إدارة الخدمة إلى مراجعات أو عمليات تدقيق منتظمة ، وتحديد إمكانيات التحسين التى يجب معالجتها من خلال مبادرات تحسين العملية .
2- الحفاظ على محفظة الخدمات :
• إضافة خدمات جديدة أو متغيرة إلى محفظة الخدمات : ويقصد به إضافة معلومات حول (مخطط) الخدمات الجديدة أو التى تم تغييرها بشكل ملحوظ إلى مجموعة الخدمات .
• تحديث محفظة الخدمات : ويقصد به تحديث المعلومات فى محفظة الخدمات .
• تنشيط الخدمات الجديدة أو المتغيرة : ويقصد به التحقق من أن الخدمات الجديدة أو التى تم تغييرها بشكل كبير جاهزة للتشغيل ، وللحصول على موافقة رسمية لتنشيط الخدمة .
• مراجعة محفظة الخدمات : ويقصد به إرسال محفظة الخدمات إلى المراجعات المنتظمة ، من أجل اكتشاف الأخطاء فى محفظة الخدمة أو التناقضات بين تعريفات الخدمة أو اتفاقيات الخدمة .
3- إدارة علاقات العملاء :
• البحث عن عملاء جدد : ويقصد به تحديد العملاء الجدد المحتملين وتقديم عروض مقدم الخدمة إلى هؤلاء العملاء الجدد المحتملين .
• توقيع اتفاقيات خدمة العملاء أو إنهائها : ويقصد به توقيع اتفاقيات خدمة العملاء مع العملاء الذين يرغبون فى استخدام خدمات مقدم الخدمة ، وتكون هذه العملية مسؤولة أيضًا عن إنهاء اتفاقيات خدمة العملاء التى لم تعد مطلوبة .
• معالجة شكاوى العملاء : ويقصد به تسجيل شكاوى العملاء وتقييم ما إذا كانت الشكاوى مبررة وتحديد الخطوات المطلوبة للتعامل مع الشكاوى .
• مراقبة شكاوى العملاء : ويقصد به المراقبة المستمرة لحالة معالجة شكاوى العملاء المعلقة واتخاذ الإجراءات التصحيحية إذا لزم الأمر .
• عقد اجتماعات العملاء : ويقصد به التواصل مع العملاء بشكل منتظم للتعرف على احتياجاتهم وخططهم المستقبلية .
• إجراء استطلاعات رضا العملاء : ويقصد به تخطيط وتنفيذ وتقييم استطلاعات رضا العملاء المنتظمة ، ويكون الهدف الرئيسى من هذه العملية هو التعرف على المجالات التى لا يتم فيها تلبية توقعات العملاء قبل فقدان العملاء لمقدمى الخدمات البديلة .
4- إدارة معلومات مكونات التهيئة :
• دعم إدارة معلومات مكونات التهيئة : ويقصد به إعداد وصيانة الأدوات اللازمة لإدارة فعالة لعناصر مكونات التهيئة (Configuration Items) ومعلومات مكونات التهيئة ذات الصلة .
• الحفاظ على نموذج مكونات التهيئة : ويقصد به تحديد الهيكل الأساسى لنموذج مكونات التهيئة (Configuration Model Structure) والحفاظ عليه ، بحيث يكون قادرًا على الاحتفاظ بجميع المعلومات حول عناصر مكونات التهيئة ، ويتضمن ذلك تحديد سمات أنواعها ومكوناتها الفرعية ، بالإضافة إلى أنواع العلاقات المطلوبة بينها .
• التحكم فى عناصر مكونات التهيئة : ويقصد به التأكد من عدم إضافة عناصر مكونات التهيئة أو تعديلها بدون التفويض المطلوب ، وأن هذه التعديلات مسجلة بشكل كاف فى نظام إدارة مكونات التهيئة .
• مراجعة التحكم فى عناصر مكونات التهيئة : ويقصد به إجراء فحوصات منتظمة ، والتأكد من أن المعلومات الواردة فى نظام إدارة مكونات التهيئة هى تمثيل دقيق لمعلومات عناصر مكونات التهيئة المثبتة بالفعل فى بيئة الإنتاج الحية .
5- تقييم التغييرات والتنسيق لها :
• دعم تقييم التغييرات : ويقصد به إعداد وصيانة الأدوات اللازمة لإدارة التغييرات بفعالية وكفاءة .
• تسجيل ومراجعة "طلبات التغيير" (Request for Changes) : ويقصد به تصفية طلبات التغيير التى لا تحتوى على جميع المعلومات المطلوبة للتقييم أو التى تعتبر غير عملية .
• تقييم التغييرات الطارئ : ويقصد به تقييم التغييرات الطارئة والتصريح بها فى أسرع وقت ممكن ، ويتم استدعاء هذه العملية إذا كان لا يمكن تطبيق إجراءات تقييم التغيير العادية .
• تقييم التغييرات (مدير التغيير) : ويقصد به تحديد مستوى التفويض المطلوب لتقييم التغيير المقترح ، ويتم تمرير تغييرات كبيرة إلى "المجلس الاستشارى للتغيير" (Change Advisory Board) للتقييم ، بينما يتم تقييم التغييرات الطفيفة على الفور والموافقة عليها من قبل مدير التغيير .
• تقييم التغييرات (المجلس الاستشارى للتغيير) : ويقصد به تقييم التغيير المقترح والتصريح به من خلال المجلس الاستشارى للتغيير . وإذا لزم الأمر ، تشارك مستويات أعلى من السلطة (مثل مجلس الإدارة) فى عملية التفويض .
• مراقبة التغييرات المفتوحة : ويقصد به مراقبة التغييرات المعلقة باستمرار فيما يتعلق بحالة تنفيذها واتخاذ الإجراءات التصحيحية حسب الاقتضاء .
• مراجعة وإغلاق التغييرات : ويقصد به تقييم مسار تنفيذ التغيير والنتائج المحققة ، من أجل التحقق من وجود تاريخ كامل للأنشطة للرجوع إليها فى المستقبل ، وللتأكد من تحليل أى أخطاء والدروس المستفادة .
6- إدارة المشاريع :
• بدء المشاريع : ويقصد به تحديد أصحاب المصلحة والمسؤوليات والموارد المتاحة للمشروع ، وتحديد المخاطر والقيود والافتراضات التى تؤثر على المشروع ، وينتج عن هذه العملية ميثاق مشروع معتمد .
• تخطيط المشاريع : ويقصد به إنشاء خطة المشروع وتحديثها .
• مراقبة المشاريع : ويقصد به رصد التقدم المحرز فى المشروع واستهلاك الموارد والإبلاغ عنه ، وبدء الإجراءات التصحيحية إذا لزم الأمر .
• مراجعة المشاريع وإغلاقها : ويقصد به تقييم مسار المشروع والنتائج المحققة ، للتأكد من تحليل أى أخطاء والدروس المستفادة .$b9_0$
