WITH ins11_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 11, 0, $h11$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (2) - إطار عمل إدارة مخاطر التكنولوجيا (TRM-F)$h11$, $t11_0$ملحق (2) - إطار عمل إدارة مخاطر التكنولوجيا (TRM-F)$t11_0$, $b11_0$وهو إطار العمل المنظم لإدارة مخاطر التكنولوجيا (TRM : Technology Risk Management) كعنصر أساسى ومتمم لإدارة مخاطر المؤسسات (ERM : Enterprise Risk Management) . ويتكون إطار العمل من العمليات الاستراتيجية على المستوى الاستراتيجى ، والعمليات التخطيطية على المستوى التنفيذى ، والإجراءات التطبيقية على المستوى التشغيلى ، ويتبنى هذا العرض لإطار عمل "إدارة مخاطر التكنولوجيا" مبدأ الرقابة على أساس المخاطر التى تتبناه الهيئة العامة للرقابة المالية ، بما يتوافق مع المعايير الدولية لأطر عمل إدارة المخاطر من المعهد الوطنى للمعايير والتكنولوجيا (NIST) لكل من التجهيزات ، والبنية التكنولوجية ، وأنظمة المعلومات ، ووسائل الحماية والتأمين . ويجوز استخدام أفضل الممارسات وأطر العمل العالمية الأخرى ، أو تبنى ممارسات بديلة بعد العرض على الهيئة لإثبات فعاليتها فى معالجة ما قد تتعرض له الشركات والجهات المالية غير المصرفية من مخاطر التكنولوجيا ، وأخذ موافقة الهيئة على هذه الممارسات البديلة ، ويشمل الضوابط الحاكمة لتوافر التجهيزات والبنية التكنولوجية وأنظمة المعلومات ووسائل الحماية والتأمين من منظور "إدارة مخاطر التكنولوجيا" :
وتنشأ المخاطر الناشئة عن استخدام التكنولوجيا من فشل أو خروقات أنظمة تكنولوجيا المعلومات أو التطبيقات أو المنصات أو البنية التحتية ، مما قد يؤدى إلى خسارة مالية أو اضطرابات فى الخدمات أو العمليات المالية غير المصرفية أو الإضرار بسمعة الشركات والجهات المالية غير المصرفية .
وتعزيز قدرتها على الصمود التكنولوجى ضد الاضطرابات التشغيلية للحفاظ على الثقة فى النظام المالى غير المصرفى ، ويتطلب التطور المتزايد للتهديدات السيبرانية أيضًا زيادة اليقظة والقدرة على الاستجابة للتهديدات الناشئة . ويجب أن يكون ضمان هذا التوافر المستمر للخدمات الأساسية للعملاء والحماية الكافية لبيانات العملاء ، من الأولويات الحرجة للشركات وللجهات المالية غير المصرفية .
ويجب على مجلس الإدارة وضع واعتماد "استراتيجية إدارة مخاطر التكنولوجيا" والتى تكون مرتبطة ومتماشية مع "استراتيجية تكنولوجيا المعلومات" ومع البنية الهيكلية لأعمال الأنشطة المالية غير المصرفية ، ويكون ذلك من خلال "إطار عمل إدارة مخاطر التكنولوجيا" والذى يكون معتمدًا من مجلس الإدارة وحاكمًا للإدارة التنفيذية وللإدارة التشغيلية . كما يجب على مجلس الإدارة أيضًا مراجعته بشكل دورى ، مرة واحدة على الأقل كل ثلاث سنوات . ويكون لمجلس الإدارة تشكيل "لجنة إدارة مخاطر التكنولوجيا" التابعة لمجلس الإدارة تكون مسئولة عن الإشراف على تنفيذ إطار عمل إدارة المخاطر والتأكد من ملائمة دورة العمل والمسئولين عن تنفيذها ، والتأكد من الالتزام بالإجراءات المطلوب اتباعها .
يشمل إطار العمل هذا على : 4 عمليات استراتيجية لدورة الحياة للمخاطر (LRP : Life-cycle Risk Process) ، تشمل "الهيكلة" (Frame) و"التقييم" (Assess) و"المجابهة" (Response) و"المراقبة" (Monitor) للمخاطر ، والتى تتكامل مع 7 عمليات استراتيجية لدورة الحياة للأنظمة وآليات التحكم (SCP : Systems & Controls Process) ، تشمل "التحضير" (Prepare) و"التصنيف" (Categorize) و"الاختيار" (Select) و"التنفيذ" (Implement) و"التقييم" (Assess) و"السماح" .
(Authorize) و"المراقبة" (Monitor) للأنظمة وآليات التحكم ، وتتضمن الأربع عمليات الاستراتيجية لدورة الحياة للمخاطر 12 عملية تخطيطية على المستوى التنفيذى ، وتتضمن السبع عمليات الاستراتيجية لدورة الحياة للأنظمة وآليات التحكم 47 عملية تخطيطية على المستوى التنفيذى . وعلى هذا يكون إجمالى العمليات على المستوى الاستراتيجى 11 عملية استراتيجية ، كما يكون إجمالى العمليات على المستوى التنفيذى 59 عملية تخطيطية .$b11_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins11_0;

WITH ins12_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 12, 0, $h12$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (2) - العمليات الاستراتيجية$h12$, $t12_0$ملحق (2) - العمليات الاستراتيجية$t12_0$, $b12_0$1- العمليات الاستراتيجية :
أولاً - العمليات الاستراتيجية لدورة الحياة للمخاطر ، وتشمل :
1- الهيكلة للمخاطر (Framing Risk) : ويقصد به إصدار استراتيجية إدارة المخاطر التى تتناول كيفية تقييم المخاطر ، والاستجابة لها ومراقبتها ، وتوضح استراتيجية إدارة المخاطر الافتراضات المحددة والقيود ودرجات تحمل المخاطر والأولويات المستخدمين لاتخاذ قرارات الاستثمار والعمليات . وتتضمن استراتيجية إدارة المخاطر أيضًا أى قرارات واعتبارات على المستوى الاستراتيجى حول كيفية إدارة المخاطر التى تتعرض لها العمليات والأصول التنظيمية والأفراد .
2- التقييم للمخاطر (Assessing Risk) : ويقصد به تحديد أولويات وتقدير المخاطر على العمليات التنظيمية للأعمال (متضمنة الرسالة والوظائف والانطباع والسمعة) ، والأصول التنظيمية للأعمال ، والأفراد ، الناتجة عن تشغيل واستخدام أنظمة المعلومات .
وتتضمن عملية تقييم المخاطر تحديد التهديدات وأوجه الضعف التى يمكن استغلالها ، من حيث احتمالية الحدوث والتأثير السلبى المحتمل (أى حجم الضرر) .
3- المجابهة للمخاطر (Responding to Risk) : ويقصد به تحديد كيفية مجابهة المخاطر ، عن طريق تقييم ، وتقرير ، وتنفيذ مسارات العمل المناسبة لقبول ، أو تجنب ، أو تخفيف ، أو مشاركة ، أو نقل المخاطر على العمليات والأصول التنظيمية ، والأفراد ، والناتجة عن تشغيل واستخدام أنظمة المعلومات .
4- المراقبة للمخاطر (Monitoring of Risk) : ويقصد به : (1) التحقق من الامتثال ، (2) تحديد الفعالية المستمرة لتدابير الاستجابة للمخاطر ، (3) تحديد التغييرات المؤثرة على المخاطر فى أنظمة المعلومات التنظيمية وبيئات التشغيل .
ويعطى تحليل نتائج المراقبة القدرة على الحفاظ على الوعى بالمخاطر التى يتم تكبدها ، وتسليط الضوء على الحاجة إلى إعادة النظر فى الخطوات الأخرى فى عملية إدارة المخاطر ، وبدء أنشطة تحسين العملية حسب الحاجة .
ثانيًا - العمليات الاستراتيجية لدورة الحياة للأنظمة وآليات التحكم (Systems & Controls Process) ، وتشمل :
1- التحضير على المستوى التنفيذى والتشغيلى للأنظمة : ويقصد به تنفيذ عمليات إدارة المخاطر بفعالية وكفاءة ، من حيث الجودة والتكلفة ، من خلال :
(1) تسهيل التواصل بين مجلس الإدارة والإدارة التنفيذية والإدارة التشغيلية ، (2) تعزيز تحديد الضوابط المشتركة والحدود الدنيا الأساسية لها لتقليل العبء على الإدارة التنفيذية والإدارة التشغيلية وتكلفة تطوير الأنظمة وحمايتها ، (3) تقليل تعقيد البنية التحتية لتكنولوجيا المعلومات من خلال تجميع وتوحيد وتحسين الأنظمة والتطبيقات من خلال نمذجة وهيكلة بنية الأعمال ، (4) تحديد وترتيب الأولويات ، وتركيز الموارد على الأصول الأعلى قيمة ، والتى تتطلب مستويات متزايدة من الحماية .
2- التصنيف للأنظمة (Categorize Systems) : ويقصد به إبلاغ عمليات ومهام إدارة المخاطر التنظيمية من خلال تحديد التأثير السلبى على العمليات والأصول التنظيمية والأفراد فيما يتعلق بفقدان السرية والنزاهة وتوافر الأنظمة والمعلومات التى تتم معالجتها وتخزينها ونقلها بواسطة تلك الأنظمة .
3- الاختيار لآليات التحكم (Select Controls) : ويقصد به تحديد الضوابط اللازمة لآليات التحكم وتخصيصها وتوثيقها لحماية نظام المعلومات والبنية الهيكلية للأعمال ، وبما يتناسب مع المخاطر التى تتعرض لها العمليات والأصول التنظيمية والأفراد .
4- التنفيذ لآليات التحكم (Implement Controls) : ويقصد به تنفيذ آليات التحكم فى خطط الأمن والخصوصية للنظام وللبنية الهيكلية للأعمال وللتوثيق فى ملف إعدادات التهيئة المرجعى .
5- التقييم لآليات التحكم (Assess Controls) : ويقصد به تحديد ما إذا كانت آليات التحكم والضوابط المختارة للتنفيذ قد تم تنفيذها بشكل صحيح ، وتعمل على النحو المنشود ، وتنتج النتيجة المرجوة فيما يتعلق بتلبية متطلبات الأمن والخصوصية للنظام وللبنية الهيكلية للأعمال .
6- السماح للأنظمة (Authorize Systems) : ويقصد به توفير المساءلة التنظيمية من خلال مطالبة مسؤول الإدارة العليا بتحديد ما إذا كانت مخاطر الأمن والخصوصية (بما فى ذلك مخاطر سلسلة التوريد) للعمليات والأصول التنظيمية أو الأفراد بناء على تشغيل نظام أو استخدام ضوابط مشتركة ، أمر مقبول .
7- المراقبة للأنظمة ولآليات التحكم (Monitor Controls) : ويقصد به الحفاظ على الوعى المستمر بالحالة حول الوضع الأمنى والخصوصية لنظام المعلومات والمنظمة لدعم قرارات إدارة المخاطر .$b12_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins12_0;

WITH ins13_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 13, 0, $h13$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (2) - العمليات التخطيطية لدورة الحياة للمخاطر$h13$, $t13_0$ملحق (2) - العمليات التخطيطية لدورة الحياة للمخاطر$t13_0$, $b13_0$2- العمليات التخطيطية :
أولاً - العمليات التخطيطية لدورة الحياة المخاطر ، وتشمل :
1- تحديد الإطار الحاكم للمخاطر (Risk Framing) :
• افتراضات المخاطر : ويقصد به تحديد الافتراضات التى تؤثر على كيفية تقييم المخاطر والاستجابة لها ومراقبتها ، متضمنة مصادر التهديد ، ونقاط الضعف ، والعواقب ، والاحتمالات .
• محددات المخاطر : ويقصد به تحديد القيود المفروضة على إجراء تقييم المخاطر والاستجابة للمخاطر وأنشطة مراقبة المخاطر .
• تحمل المخاطر : ويقصد به تحديد مستوى تحمل المخاطر على مستوى البنية الهيكلية للأعمال .
• الأولويات والمفاضلات : ويقصد به تحديد الأولويات والمفاضلات بين البدائل فى إدارة المخاطر .
2- تقييم المخاطر (Risk Assessment) :
• تحديد التهديدات وأوجه الضعف : ويقصد به تحديد التهديدات ونقاط الضعف فى أنظمة المعلومات التنظيمية والبيئات التى تعمل فيها الأنظمة .
• تحديد المخاطر : ويقصد به تحديد المخاطر على العمليات والأصول التنظيمية والأفراد إذا ما تمكنت التهديدات المحددة من استغلال نقاط الضعف المحددة .
3- المجابهة للمخاطر (Responding to Risk) :
• تحديد المجابهة للمخاطر : ويقصد به تحديد مسارات العمل البديلة للاستجابة للمخاطر المحددة أثناء تقييم المخاطر ، والتى قد تتضمن قبول المخاطر ، وتجنب المخاطر ، والتخفيف من حدة المخاطر ، وتقاسم المخاطر أو تحويلها .
• تقييم البدائل : ويقصد به تقييم مسارات العمل البديلة للاستجابة للمخاطر .
• اتخاذ قرار الاستجابة للمخاطر : ويقصد به تحديد مسار العمل المناسب للاستجابة للمخاطر .
• تنفيذ الاستجابة للمخاطر : ويقصد به تنفيذ مسار العمل المختار للاستجابة للمخاطر .
4- المراقبة للمخاطر (Monitoring Risk) :
• استراتيجية مراقبة المخاطر : ويقصد به تطوير استراتيجية مراقبة المخاطر والتى تتضمن الغرض من أنشطة المراقبة وأنواعها وتوقيتات تكرارها .
• مراقبة المخاطر : ويقصد به مراقبة أنظمة المعلومات التنظيمية وبيئات التشغيل على أساس مستمر للتحقق من الامتثال ، وتحديد فعالية تدابير الاستجابة للمخاطر ، وتحديد التغييرات .$b13_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins13_0;

WITH ins14_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 14, 0, $h14$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (2) - العمليات التخطيطية لدورة الحياة للأنظمة وآليات التحكم (1 إلى 3)$h14$, $t14_0$ملحق (2) - العمليات التخطيطية لدورة الحياة للأنظمة وآليات التحكم (1 إلى 3)$t14_0$, $b14_0$ثانيًا - العمليات التخطيطية لدورة الحياة للأنظمة وآليات التحكم :
1- التحضير على المستوى التنفيذى والتشغيلى للأنظمة (Prepare Executive & Operational Levels) .
التحضير على المستوى التنفيذى للأنظمة :
• أدوار إدارة المخاطر : ويقصد به تحديد الأفراد وتعيين أدوار رئيسية لتنفيذ إطار عمل إدارة المخاطر .
• استراتيجية إدارة المخاطر : ويقصد به وضع استراتيجية لإدارة المخاطر تتضمن تحديدًا وتعبيرًا عن تحمل المخاطر التنظيمية .
• تقييم المخاطر التنظيمية للأعمال : ويقصد به اكتمال تقييم المخاطر على المستوى التنظيمى للأعمال أو تحديث تقييم المخاطر الحالى .
• الحدود الدنيا الأساسية لآليات التحكم : ويقصد به تحديد وإتاحة الحدود الدنيا الأساسية لآليات التحكم ، والتى تكون مخصصة ومتناسقة مع إطار عمل الأمن السيبرانى .
• تحديد آليات التحكم المشتركة : ويقصد به تحديد وتوثيق ونشر آليات التحكم المشتركة المتاحة لأنظمة المعلومات المختلفة .
• تحديد أولويات مستوى التأثير : ويقصد به أن يتم تحديد أولويات أنظمة المعلومات من حيث مستوى التأثير .
• استراتيجية المراقبة المستمرة على المستوى التنفيذى : ويقصد به تطوير وتنفيذ استراتيجية لمراقبة فعالية الرقابة على المستوى التنفيذى للأنظمة .
التحضير على المستوى التشغيلى للأنظمة :
• التركيز على الرسالة والغرض ووظائف الأعمال : ويقصد به تحديد الرسالة والغرض ووظائف الأعمال المهمة التى يهدف النظام إلى دعمها .
• أصحاب المصلحة فى النظام : ويقصد به تحديد أصحاب المصلحة الذين لهم مصلحة فى النظام .
• تحديد الأصول : ويقصد به تحديد وترتيب أهمية الأصول لأصحاب المصلحة .
• حدود الحصول على الصلاحية : ويقصد به تحديد الحدود التى يلزم الحصول على صلاحية للدخول من خلالها على النظام .
• أنواع المعلومات : ويقصد به تحديد أنواع المعلومات التى تتم معالجتها وتخزينها ونقلها بواسطة النظام .
• دورة حياة المعلومات : ويقصد به تحديد وفهم جميع مراحل دورة حياة المعلومات لكل نوع من أنواع المعلومات التى تتم معالجتها أو تخزينها أو نقلها بواسطة النظام .
• تقييم المخاطر على المستوى التشغيلى للنظام : ويقصد به اكتمال تقييم المخاطر على مستوى النظام أو تحديث تقييم المخاطر الحالى .
• تعريف المتطلبات : ويقصد به تحديد متطلبات الأمن والخصوصية وتحديد أولوياتها .
• البنية الهيكلية للأعمال : ويقصد به تحديد وضع النظام داخل البنية الهيكلية للأعمال .
• تخصيص المتطلبات : ويقصد به تخصيص متطلبات الأمن والخصوصية للنظام وللبيئة التى يعمل فيها النظام .
• تسجيل النظام : ويقصد به تسجيل النظام لأغراض الإدارة والمساءلة والتنسيق والإشراف .
2- التصنيف للأنظمة (Categorize Systems) :
• وصف نظام : ويقصد به وصف وتوثيق خصائص النظام .
• التصنيف الأمنى : ويقصد به تحديد التصنيف الأمنى للنظام ، بما فى ذلك المعلومات التى تتم معالجتها بواسطة النظام ، وعلى أن يتم توثيق نتائج التصنيف الأمنى فى خطط الأمن والخصوصية وإدارة مخاطر سلسلة الإمدادات (Supply Chain Risk Management) ، وعلى أن تتوافق نتائج التصنيف الأمنى مع البنية الهيكلية للأعمال ، وعلى أن تعكس نتائج التصنيف الأمنى استراتيجية إدارة المخاطر المعتمدة .
• مراجعة التصنيف الأمنى والموافقة عليه : ويقصد به مراجعة نتائج التصنيف الأمنى والموافقة على قرار التصنيف من قبل الإدارة العليا .
3- الاختيار لآليات التحكم (Select Controls) :
• اختيار آليات التحكم : ويقصد به اختيار الحدود الدنيا الأساسية لضوابط وآليات التحكم لحماية النظام بما يتناسب مع المخاطر .
• تفصيل آليات التحكم : ويقصد به تفصيل الحدود الدنيا الأساسية لآليات التحكم لحماية النظام بما يتناسب مع المخاطر .
• تخصيص آليات التحكم : ويقصد به وجود منهجية لآليات التحكم مخصصة لنظام ، أو مشتركة لمجموعة من الأنظمة ، أو مختلطة ، وعلى أن يتم تحديد عناصر آليات التحكم (أى عناصر آلية أو فيزيائية أو بشرية) .
• توثيق عمليات تنفيذ التحكم المخطط لها : ويقصد به توثيق آليات التحكم وإجراءات التخصيص المرتبطة بها فى خطط الأمن والخصوصية أو المستندات المكافئة .
• استراتيجية المراقبة المستمرة للنظام : ويقصد به تطوير استراتيجية مراقبة مستمرة للنظام تعكس استراتيجية إدارة المخاطر .
• مراجعة الخطة والموافقة عليها : ويقصد به مراجعة واعتماد خطط الأمن والخصوصية التى تعكس اختيار آليات التحكم والضوابط اللازمة لحماية النظام وبيئة التشغيل المتناسبة مع المخاطر والموافقة عليها من قبل مسئول إدارة المخاطر التكنولوجية .$b14_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins14_0;

WITH ins15_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 15, 0, $h15$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (2) - العمليات التخطيطية لدورة الحياة للأنظمة وآليات التحكم (4 إلى 7)$h15$, $t15_0$ملحق (2) - العمليات التخطيطية لدورة الحياة للأنظمة وآليات التحكم (4 إلى 7)$t15_0$, $b15_0$4- التنفيذ لآليات التحكم (Implement Controls) :
• تنفيذ آليات التحكم : ويقصد به تنفيذ آليات التحكم والضوابط المحددة فى خطط الأمن والخصوصية النظام .
• تحديث معلومات تنفيذ آليات التحكم : ويقصد به توثيق التغييرات على التنفيذ المخطط لآليات التحكم والضوابط ، وعلى أن يتم تحديث خطط الأمن والخصوصية بناءً على المعلومات التى تم الحصول عليها أثناء تنفيذ آليات التحكم والضوابط .
5- التقييم لآليات التحكم (Assess Controls) :
• اختيار المقيم للمهمة : ويقصد به اختيار مقيم أو فريق تقييم لإجراء تقييمات آليات التحكم ، وعلى أن يتم تحقيق المستوى المناسب من الاستقلالية للمقيم أو فريق التقييم المختار .
• خطة التقييم للمهمة : ويقصد به توفير الوثائق اللازمة لإجراء التقييمات للمقيم أو فريق التقييم ، وعلى أن يتم تطوير وتوثيق خطط تقييم الأمان والخصوصية ، ويتم مراجعة واعتماد خطط تقييم الأمان والخصوصية لتحديد التوقعات لتقييم الرقابة ومستوى الجهد المطلوب .
• تقييمات آليات التحكم : ويقصد به إجراء تقييمات آليات التحكم وفقًا لخطط تقييم الأمن والخصوصية ، وعلى أن يتم النظر فى فرص إعادة استخدام نتائج التقييم من التقييمات السابقة لتحسين فعالية عملية إدارة المخاطر من حيث الوقت والتكلفة ، وعلى أن يتم تعظيم استخدام التشغيل الآلى automation لإجراء تقييمات التحكم لزيادة سرعة وفعالية وكفاءة التقييمات .
• تقارير تقييم المهام : ويقصد به إصدار تقارير تقييم الأمن والخصوصية التى توفر النتائج والتوصيات .
• إجراءات المعالجة : ويقصد به اتخاذ إجراءات تصحيحية لمعالجة أوجه القصور فى آليات التحكم والضوابط المطبقة فى نظام وبيئة التشغيل ، وعلى أن يتم تحديث خطط الأمن والخصوصية لتعكس تغييرات تنفيذ آليات التحكم التى تم إجراؤها بناءً على التقييمات وإجراءات العلاج اللاحقة .
• خطة العمل ومخرجات محددة : ويقصد به وضع خطة عمل ومخرجات محددة عن خطط العلاج المقترحة للمخاطر غير المقبولة بناء على تقارير تقييم الأمن والخصوصية .
6- السماح للأنظمة (Authorize Systems) :
• متطلبات ومرفقات السماح : ويقصد به تحديد متطلبات والمرفقات اللازم توفيرها وتقديمها للمسئول للموافقة على السماح للنظام أو لآليات التحكم بالتشغيل فى البيئة الإنتاجية .
• تحليل المخاطر وتحديدها : ويقصد به تقديم تحديد للمخاطر من قبل المسؤول المفوض يعكس استراتيجية إدارة المخاطر بما فى ذلك تحمل المخاطر .
• الاستجابة للمخاطر : ويقصد به توفير استجابات للمخاطر ، بناءً على المخاطر المحددة .
• قرار السماح : ويقصد به اتخاذ قرار الموافقة على أو رفض طلب السماح الخاص بالنظام أو آليات التحكم العامة .
• تقرير السماح : ويقصد به الإبلاغ عن قرارات السماح ونقاط الضعف الكبيرة والمخاطر للإدارة العليا .
7- المراقبة للأنظمة ولآليات التحكم (Monitor Controls) :
• تغييرات النظام والبيئة : ويقصد به مراقبة نظام المعلومات وبيئة التشغيل وفقًا لاستراتيجية المراقبة المستمرة .
• التقييمات الجارية : ويقصد به إجراء التقييمات المستمرة لفعالية الرقابة وفقًا لاستراتيجية المراقبة المستمرة .
• الاستجابة للمخاطر المستمرة : ويقصد به تحليل مخرجات أنشطة المراقبة المستمرة والاستجابة لها بشكل مناسب .
• تحديثات متطلبات ومرفقات السماح : ويقصد به تحديث وثائق إدارة المخاطر بناءً على أنشطة المراقبة المستمرة .
• الإبلاغ عن الأمن والخصوصية : ويقصد به إيجاد عملية للإبلاغ عن وضع الأمن والخصوصية إلى المسؤول المفوض وغيره من الإدارة العليا .
• السماح المستمر : ويقصد به قيام مسئولى الموافقة على السماح للأنظمة ولآليات التحكم باستخدام نتائج أنشطة المراقبة المستمرة والإبلاغ عن التغييرات فى تحديد المخاطر وقرارات القبول .
• التخلص من نظام : ويقصد به تطوير وتنفيذ استراتيجية للتخلص من النظام ، حسب الحاجة .$b15_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins15_0;

WITH ins16_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 16, 0, $h16$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (3) - إطار عمل إدارة الأمن السيبراني (CSM-F)$h16$, $t16_0$ملحق (3) - إطار عمل إدارة الأمن السيبراني (CSM-F)$t16_0$, $b16_0$وهو إطار العمل المنظم لإدارة الأمن السيبرانى (Cybersecurity Management) كعنصر أساسى ومتمم لإدارة أمن المؤسسات (ESM : Enterprise Security Management) . ويتكون إطار العمل من العمليات الاستراتيجية على المستوى الاستراتيجى ، والعمليات التخطيطية على المستوى التنفيذى ، والإجراءات التطبيقية على المستوى التشغيلى ، وتتبنى الهيئة مبدأ الموائمة بين "إدارة الأمن السيبراني" ، و"إدارة المخاطر التكنولوجية" ، حيث تكون المخاطر السيبرانية أحد أنواع المخاطر التكنولوجية . وعلى هذا تكون دورة حياة إدارة المخاطر السيبرانية على المستوى الاستراتيجى مماثلة لدورة حياة إدارة المخاطر التكنولوجية ("الهيكلة" و"التقييم" و"المجابهة" و"المراقبة" للمخاطر التكنولوجية) .
ومن خلال فهم درجة تحمل المخاطر ، يمكن للشركات أو الجهات المالية غير المصرفية تحديد الأولوية لأنشطة الأمن السيبرانى ، مما يمكن من اتخاذ قرارات مستنيرة بشأن نفقات الأمن السيبرانى . ويوفر تنفيذ مبادرات إدارة المخاطر القدرة على تحديد التعديلات والإبلاغ عنها لمبادرات الأمن السيبرانى . وقد يتم التعامل مع المخاطر بطرق مختلفة ، بما فى ذلك تخفيف المخاطر ، أو تحويل المخاطر ، أو تجنب المخاطر ، أو قبول المخاطر ، اعتمادًا على التأثير المحتمل على تقديم الخدمات الهامة .
وتعمل الضوابط المنصوص عليها كدليل للممارسات السليمة لإدارة الأمن السيبرانى والمخاطر السيبرانية .
ويتبنى هذا العرض لإطار عمل "إدارة الأمن السيبراني" ، منهجية "دورة الحياة لتحسين الأمن السيبراني" من المعهد الوطنى للمعايير والتكنولوجيا (NIST : National Institute for Standards & Technology) لكل من التجهيزات ، والبنية التكنولوجية ، وأنظمة المعلومات ، ووسائل الحماية والتأمين .
ويجب على مجلس الإدارة وضع واعتماد "استراتيجية إدارة الأمن السيبراني" والتى تكون مرتبطة ومتماشية مع "استراتيجية تكنولوجيا المعلومات" ومع البنية الهيكلية لأعمال الأنشطة المالية غير المصرفية ، ويكون ذلك من خلال "إطار عمل إدارة الأمن السيبراني" والذى يكون معتمدًا من مجلس الإدارة وحاكمًا للإدارة التنفيذية وللإدارة التشغيلية . كما يجب على مجلس الإدارة أيضًا مراجعته بشكل دورى ، مرة واحدة على الأقل كل ثلاث سنوات . ويكون لمجلس الإدارة تشكيل "لجنة إدارة الأمن السيبراني" التابعة لمجلس الإدارة تكون مسئولة عن الإشراف على تنفيذ إطار عمل إدارة الأمن السيبرانى والتأكد من ملائمة دورة العمل والمسئولين عن تنفيذها ، والتأكد من الالتزام بالإجراءات المطلوب اتباعها .
ويشتمل هذا الإطار على : 5 عمليات استراتيجية لدورة الحياة للأمن السيبرانى (Cybersecurity Process) ، تشمل "التحديد" (Identify) و"الحماية" (Protect) و"الرصد" (Detect) و"الاستجابة" (Respond) و"الاستعادة" (Recover) للأمن السيبرانى وما تتضمنه من 23 عملية استراتيجية فرعية ، وما يرتبط بهم من 108 عملية تخطيطية على المستوى التنفيذى .$b16_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins16_0;

WITH ins17_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 17, 0, $h17$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (3) - العمليات الاستراتيجية$h17$, $t17_0$ملحق (3) - العمليات الاستراتيجية$t17_0$, $b17_0$1- العمليات الاستراتيجية :
العمليات الاستراتيجية لدورة حياة الأمن السيبرانى (Cybersecurity Process) ، وتشمل :
1- التحديد (Identify) : ويقصد به تطوير الفهم التنظيمى لإدارة مخاطر الأمن السيبرانى للأنظمة والأصول والبيانات والقدرات .
• إدارة الأصول (Asset Management) : ويقصد به تحديد وإدارة البيانات والموظفين والأجهزة والأنظمة والمرافق التى تمكن الشركة أو الجهة المالية غير المصرفية من تحقيق أغراض العمل بما يتوافق مع أهميتها النسبية للأهداف التنظيمية واستراتيجية المخاطر لها .
• بيئة الأعمال (Business Environment) : ويقصد به فهم رسالة الشركة أو الجهة المالية غير المصرفية وأهدافها وأصحاب المصلحة وأنشطتها وتحديد أولوياتها ؛ وتستخدم هذه المعلومات لإبلاغ أدوار ومسؤوليات وقرارات إدارة المخاطر فى مجال الأمن السيبرانى .
• الحوكمة (Governance) : ويقصد بها فهم السياسات والإجراءات والعمليات لإدارة ومراقبة المتطلبات التنظيمية والقانونية والمتعلقة بالمخاطر البيئية والتشغيلية وإبلاغ إدارة مخاطر الأمن السيبرانى .
• تقييم المخاطر (Risk Assessment) : ويقصد به تفهم الشركة أو الجهة المالية غير المصرفية مخاطر الأمن السيبرانى للعمليات التنظيمية (بما فى ذلك الرسالة أو الوظائف أو الانطباع أو السمعة) والأصول التنظيمية والأفراد .
• استراتيجية إدارة المخاطر (Risk Management Strategy) : ويقصد به وضع أولويات الشركة أو الجهة المالية غير المصرفية والقيود وتحمل المخاطر والافتراضات واستخدامها لدعم قرارات المخاطر التشغيلية .
• إدارة مخاطر سلسلة التوريد (Supply Chain Risk Management) : ويقصد به وضع أولويات الشركة أو الجهة المالية غير المصرفية والقيود ودرجة تحمل المخاطر والافتراضات واستخدامها لدعم قرارات المخاطر المرتبطة بإدارة مخاطر سلسلة التوريد . ويتم تخطيط وتنفيذ عمليات لتحديد وتقييم وإدارة مخاطر سلسلة التوريد .
2- الحماية (Protect) : ويقصد بها تطوير وتنفيذ الضمانات المناسبة لضمان تقديم خدمات البنية التحتية الحيوية .
• إدارة الهوية والمصادقة والتحكم فى الوصول (Authentication & Access Control) : ويقصد به الوصول إلى الأصول المادية والمنطقية والملحقات المرتبطة بها على المستخدمين المعتمدين والعمليات والأجهزة ، ويتم إدارتها بما يتفق مع المخاطر المقدرة للوصول غير المصرح به إلى الأنشطة والمعاملات المصرح بها .
• الوعى والتدريب (Awareness & Training) : ويقصد به تزويد موظفى الشركة أو الجهة المالية غير المصرفية وشركائها بالتثقيف للتوعية بالأمن السيبرانى ويتم تدريبهم على أداء واجباتهم ومسؤولياتهم المتعلقة بالأمن السيبرانى بما يتفق مع السياسات والإجراءات والاتفاقيات ذات الصلة .
• أمن البيانات (Data Security) : ويقصد به إدارة المعلومات والسجلات (البيانات) بما يتوافق مع استراتيجية المخاطر لحماية سرية المعلومات وسلامتها وتوافرها .
• عمليات وإجراءات حماية المعلومات (Information Protection Processes & Procedures) : ويقصد به الحفاظ على السياسات الأمنية (التى تتناول الغرض والنطاق والأدوار والمسؤوليات والتزام الإدارة والتنسيق بين الكيانات التنظيمية) والعمليات والإجراءات وتستخدم لإدارة حماية أنظمة المعلومات والأصول .
• الصيانة (Maintenance) : ويقصد به إجراء عمليات الصيانة والإصلاح لمكونات أنظمة التحكم والمعلومات الصناعية بما يتفق مع السياسات والإجراءات .
• التكنولوجيا الوقائية (Protective Technology) : ويقصد به أن تدار الحلول الأمنية التكنولوجية لضمان أمن ومرونة الأنظمة والأصول ، بما يتوافق مع السياسات والإجراءات والاتفاقيات ذات الصلة .
3- الرصد (Detect) : ويقصد به تطوير وتنفيذ الإجراءات المناسبة لاكتشاف وتحديد وقوع حدث الأمن السيبرانى .
• الأحداث غير المألوفة والنمطية (Anomalies & Events) : ويقصد به الكشف عن الأنشطة غير المألوفة وفهم التأثير المحتمل للأحداث .
• المراقبة الأمنية المستمرة (Security Continuous Monitoring) : ويقصد به مراقبة نظام المعلومات والأصول لتحديد أحداث الأمن السيبرانى والتحقق من فعالية تدابير الحماية .
• تحسين عملية الرصد (Detection Process Improvement) : ويقصد به تحديث عملية الرصد وإجراءاتها واختبارها بما يتناسب مع ما يطرأ من أحداث غير متوقعة .
4- الاستجابة (Respond) : ويقصد به تطوير وتنفيذ الاجراءات المناسبة لاتخاذ التدابير المتعلقة بحدث الأمن السيبرانى المكتشف .
• تخطيط الاستجابة (Response Planning) : ويقصد به تنفيذ عمليات وإجراءات الاستجابة والحفاظ عليها لضمان الاستجابة لحوادث الأمن السيبرانى المكتشفة .
• التواصل بخصوص الاستجابة (Response Communications) : ويقصد به أن يتم تنسيق إجراءات الاستجابة مع أصحاب المصلحة الداخليين والخارجيين (مثل الدعم الخارجى من وكالات إنفاذ القانون) .
• التحليل (Response Analysis) : ويقصد به إجراء التحليل لضمان الاستجابة الفعالة ودعم إجراءات التعافى .
• تدابير التخفيف (Mitigation) : ويقصد به اتخاذ التدابير التى من شأنها منع تفاقم الحدث ، والتخفيف من آثاره ، وحل مسبباته .
• تحسين عملية الاستجابة (Respond Process Improvement) : ويقصد به أن يتم تحسين إجراءات الاستجابة من خلال دمج الدروس المستفادة من إجراءات الرصد أو الاستجابة الحالية والسابقة .
5- الاستعادة (Recover) : ويقصد به تطوير وتنفيذ الإجراءات المناسبة للحفاظ على خطط المرونة واستعادة أى قدرات أو خدمات تعرضت للضرر بسبب حدث للأمن السيبرانى .
• تخطيط الاستعادة (Recovery Planning) : ويقصد به تنفيذ عمليات وإجراءات الاسترداد وصيانتها لضمان استعادة الأنظمة أو الأصول المتأثرة بحوادث الأمن السيبرانى .
• تحسين عملية الاستعادة (Recover Process Improvement) : ويقصد به تحسين تخطيط الاسترداد وعملياته من خلال دمج الدروس المستفادة فى الأنشطة المستقبلية .
• التواصل بخصوص الاستعادة (Recovery Communications) : ويقصد به تنسيق أنشطة الاستعادة مع أطراف داخلية وخارجية (مثل مراكز التنسيق بالاتحادات والهيئة ومقدمى خدمة الإنترنت ومسئولى الأنظمة مصدر الهجوم ومسئولى الأنظمة المتعرضة للهجوم وفرق مجابهة أحداث الأمن السيبرانى الأخرى مثل وزارة الاتصالات والموردين للأنظمة المصدرة والمتعرضة للهجوم) .$b17_0$
  FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision'
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING
  RETURNING id, body
)
INSERT INTO article_versions (article_id, version_no, body, effective_from, status)
SELECT id, 1, body, '2023-07-12', 'active' FROM ins17_0;

WITH ins18_0 AS (
  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, title, body)
  SELECT id, 18, 0, $h18$القواعد المرفقة بقرار مجلس إدارة الهيئة رقم 139 لسنة 2023 - ملحق (3) - العمليات التخطيطية لدورة حياة الأمن السيبرانى (التحديد والحماية)$h18$, $t18_0$ملحق (3) - العمليات التخطيطية لدورة حياة الأمن السيبرانى (التحديد والحماية)$t18_0$, $b18_0$2- العمليات التخطيطية :
العمليات التخطيطية لدورة الحياة للأمن السيبرانى (Cybersecurity Process) :
1- التحديد (Identify) :
إدارة الأصول (Asset Management) وتشتمل على :
• جرد الأجهزة والأنظمة المادية للشركة أو الجهة المالية غير المصرفية .
• جرد منصات البرامج والتطبيقات للشركة أو الجهة المالية غير المصرفية .
• تحديد آليات ومسارات التواصل وتدفق البيانات على المستوى التنظيمى .
• فهرسة أنظمة المعلومات الخارجية .
• تحديد أولويات الموارد (على سبيل المثال ، الأصول الملموسة ، والأجهزة ، والبيانات ، والوقت ، والموظفين ، والبرامج) بناءً على تصنيفها وأهميتها وقيمة الأعمال .
• إنشاء أدوار ومسؤوليات الأمن السيبرانى لجميع القوى العاملة وأصحاب المصلحة من الأطراف الثالثة (مثل الموردين والعملاء والشركاء) .
بيئة الأعمال (Business Environment) وتشتمل على :
• تحديد دور الشركة أو الجهة المالية غير المصرفية فى سلسلة التوريد والإفصاح عنه .
• تحديد مكان الشركة أو الجهة المالية غير المصرفية فى البنية التحتية الحيوية وقطاعها السوقى والإفصاح عنها .
• تحديد أولويات الرسالة والأهداف والأنشطة التنظيمية والإفصاح عنها .
• إنشاء التبعيات والوظائف الرئيسية لتقديم الخدمات الحيوية .
• وضع متطلبات المرونة لدعم تقديم الخدمات الحيوية لجميع حالات التشغيل (على سبيل المثال ، أثناء وقوع الخطر / الهجوم ، أثناء التعافى ، العمليات العادية) .
الحوكمة (Governance) وتشتمل على :
• وضع سياسة الأمن السيبرانى التنظيمى والإفصاح عنها .
• تنسيق أدوار ومسؤوليات الأمن السيبرانى ومواءمتها مع الأدوار الداخلية والشركاء الخارجيين .
• التحقق من أن المتطلبات القانونية والتنظيمية المتعلقة بالأمن السيبرانى ، بما فى ذلك التزامات الخصوصية والحريات المدنية ، مفهومة ومدارة .
• التحقق من أن عمليات الحوكمة وإدارة المخاطر قادرة على مجابهة مخاطر الأمن السيبرانى .
تقييم المخاطر (Risk Assessment) وتشتمل على :
• تحديد وتوثيق ثغرات الأصول .
• تلقى معلومات التهديد السيبرانى من منتديات ومصادر مشاركة المعلومات .
• تحديد وتوثيق التهديدات ، الداخلية منها والخارجية .
• تحديد التأثيرات والاحتمالات المتوقعة على الأعمال .
• استخدام التهديدات ونقاط الضعف والاحتمالات والتأثيرات لتحديد المخاطر .
• تحديد الاستجابات للمخاطر وترتيبها حسب الأولوية .
استراتيجية إدارة المخاطر (Risk Management Strategy) وتشتمل على :
• إنشاء عمليات إدارة المخاطر وإدارتها والموافقة عليها من قبل أصحاب المصلحة التنظيميين .
• تحديد درجة تحمل المخاطر التنظيمية والتعبير عنها بوضوح .
• الأخذ فى الاعتبار دور الشركة أو الجهة المالية غير المصرفية فى القطاع السوقى وفى البنية التحتية الحيوية الداعمة للقطاع السوقى ، عند تحديد درجة تحمل المخاطر .
إدارة مخاطر سلسلة التوريد (Supply Chain Risk Management) :
• تحديد عمليات إدارة مخاطر سلسلة التوريد السيبرانى وإنشاءها وتقييمها وإدارتها والموافقة عليها من قبل أصحاب المصلحة التنظيميين .
• تحديد الموردين والشركاء الخارجيين لأنظمة المعلومات والمكونات والخدمات وتحديد أولوياتها وتقييمها باستخدام عملية تقييم مخاطر سلسلة التوريد للتكنولوجيا .
• استخدم العقود المبرمة مع الموردين والشركاء الخارجيين لتنفيذ التدابير المناسبة المصممة لتلبية أهداف برنامج الأمن .
• السيبرانى للشركة أو الجهة المالية غير المصرفية وخطة إدارة مخاطر سلسلة التوريد السيبرانى .
• تقييم الموردين والشركاء الخارجيين بشكل روتينى باستخدام عمليات التدقيق أو نتائج الاختبارات أو غيرها من أشكال التقييم للتأكد من وفائهم بالتزاماتهم التعاقدية .
• إجراء تخطيط واختبار الاستجابة والاسترداد مع الموردين ومقدمى خدمات التعهيد .
2- الحماية (Protect) :
إدارة الهوية والمصادقة والتحكم فى الوصول (Authentication & Access Control) وتشتمل على :
• إصدار الهويات وبيانات الاعتماد وإدارتها والتحقق منها وإبطالها وتدقيقها للأجهزة والمستخدمين والعمليات المصرح لهم .
• إدارة وحماية الوصول المادى إلى الأصول .
• إدارة الوصول عن بعد .
• إدارة أذونات وتصاريح الوصول ، بما فى ذلك مبادئ الحد الأدنى من الامتياز والفصل بين الواجبات .
• سلامة الشبكة محمية (على سبيل المثال ، الفصل بين الشبكات وتجزئة الشبكة) .
• إثبات الهوية الرقمية وربطها بعوامل التعريف والتأكيد عليها فى كل المعاملات طبقًا لضوابط الهيئة الصادرة فى هذا الشأن .
• المصادقة على المستخدمين والأجهزة والأصول الأخرى (على سبيل المثال ، عامل واحد ، أكثر من عامل) بما يتناسب مع مخاطر المعاملة (على سبيل المثال ، مخاطر أمن وخصوصية الأفراد والمخاطر التنظيمية الأخرى) وطبقًا لضوابط الهيئة الصادرة فى هذا الشأن .
الوعى والتدريب (Awareness & Training) وتشتمل على :
• إعلام جميع المستخدمين وتدريبهم .
• فهم المستخدمين المتميزين أدوارهم ومسؤولياتهم .
• فهم أصحاب المصلحة من الأطراف الثالثة (مثل الموردين والعملاء والشركاء) أدوارهم ومسؤولياتهم .
• فهم المديرين التنفيذيين أدوارهم ومسؤولياتهم .
• فهم موظفو الأمن المادى والأمن السيبرانى أدوارهم ومسؤولياتهم .
أمن البيانات (Data Security) وتشتمل على :
• حماية البيانات المخزنة .
• حماية البيانات المنقولة .
• تدار الأصول طبقًا للسياسات الحاكمة فى حالات الإهلاك والتحويل والتصرف .
• الحفاظ على القدرة الكافية لضمان التوافر .
• تنفيذ الحماية ضد تسرب البيانات .
• استخدام آليات قياس السلامة للتحقق من سلامة البرمجيات وأنظمة التشغيل والبرمجيات وسلامة المعلومات .
• بيئة التطوير والاختبار منفصلة عن بيئة الإنتاج .
• استخدام آليات قياس السلامة للتحقق من سلامة الأجهزة .
عمليات وإجراءات حماية المعلومات (Information Protection Processes & Procedures) وتشتمل علي :
• تطوير وصيانة الحدود الدنيا الأساسية لآليات التحكم ولضوابط تكنولوجيا المعلومات يتضمن مبادئ الأمن الأساسية (مثل مفهوم الحد الأدنى من الوظائف) .
• تنفيذ دورة حياة تطوير الأنظمة – SDLC .
• التأكد من الالتزام بعمليات التحكم فى تغيير بيانات التهيئة لعناصر المكونات .
• إجراء نسخ احتياطية للمعلومات وصيانتها واختبارها .
• استيفاء السياسة واللوائح المتعلقة ببيئة التشغيل المادية للأصول التنظيمية .
• إهلاك البيانات وفقًا للسياسة المعتمدة .
• تحسين عمليات الحماية .
• التحقق من فعالية تقنيات الحماية مشتركة .
• خطط الاستجابة (الاستجابة للحوادث واستمرارية الأعمال) وخطط التعافى (التعافى من الحوادث والتعافى من الكوارث) قيد الإدارة التنفيذية والتشغيلية .
• اختبار خطط الاستجابة والتعافى .
• تضمين الأمن السيبرانى فى ممارسات الموارد البشرية .
• تطوير وتنفيذ خطة إدارة نقاط الضعف .
الصيانة (Maintenance) وتشتمل على :
• تنفيذ عمليات الصيانة والإصلاح للأصول التنظيمية وتسجيلها باستخدام الأدوات المعتمدة والتى تم معايرتها .
• الموافقة على الصيانة عن بعد للأصول التنظيمية وتسجيلها وتنفيذها بطريقة تمنع الوصول غير المصرح به .
التكنولوجيا الوقائية (Protective Technology) وتشتمل على :
• تحديد سجلات التدقيق أو التسجيل وتوثيقها وتنفيذها ومراجعتها وفقًا للسياسة المعتمدة وطبقًا لضوابط الهيئة الصادرة فى شأن السجلات الرقمية .
• حماية الوسائل القابلة للإزالة ويقيد استخدامها وفقًا للسياسة المعتمدة .
• استخدام مبدأ "الوظيفة الأقل لزوما" فى إعدادات التهيئة لعناصر مكونات الأنظمة لتوفير القدرات الأساسية فقط .
• التأكد من حماية شبكات الاتصالات والتحكم .
• تنفيذ آليات المرونة (على سبيل المثال ، "التشغيل الآمن فى حالة حدوث فشل" ، و"توزيع الأحمال" ، و"تبديل المكونات أثناء التشغيل الحي") لتحقيق متطلبات المرونة فى المواقف العادية والمعاكسة .$b18_0$
