DO $verify156$
DECLARE
  v_law_id uuid;
  v_n int; v_v int; v_bad int; v_len int;
BEGIN
  SELECT id INTO v_law_id FROM laws WHERE law_no = 139 AND law_year = 2023 AND kind = 'board_decision';
  IF v_law_id IS NULL THEN
    RAISE WARNING '[156] القرار 139/2023 غير موجود — لا تحقق';
    RETURN;
  END IF;
  SELECT count(*), COALESCE(sum(length(body)), 0) INTO v_n, v_len FROM articles WHERE law_id = v_law_id;
  IF v_n <> 20 THEN RAISE EXCEPTION '[156] عدد المواد % بدل 20', v_n; END IF;
  SELECT count(*) INTO v_v FROM article_versions av JOIN articles a ON a.id = av.article_id WHERE a.law_id = v_law_id AND av.version_no = 1 AND av.status = 'active' AND av.effective_from = DATE '2023-07-12';
  IF v_v <> 20 THEN RAISE EXCEPTION '[156] عدد النسخ % بدل 20', v_v; END IF;
  SELECT count(*) INTO v_bad FROM articles WHERE law_id = v_law_id AND (body ~ '[٠-٩۰-۹]' OR body ~ '[ٌ-ْ]' OR body LIKE '%' || chr(65533) || '%' OR body LIKE '%ـ%' OR body LIKE '%التجهيزات التحتية (Facilities%' OR body LIKE '%اللازمة لنقل البيانات%' OR body LIKE '%بالتعاملين%' OR body LIKE '%الاستداد%' OR body LIKE '%Outsourcing Service%' OR body LIKE '%الوقائع المصرية –%' OR body LIKE '%تابع (أ) فى 11%' OR body LIKE '%رقم 139 لسنة%' OR body LIKE '%حوادث الخدمة التى%' OR body LIKE '%المطلوبة لنشر مكونات الخدمة%');
  IF v_bad > 0 THEN RAISE EXCEPTION '[156] % مادة بها تلف أو بقايا OCR أو ترويسة', v_bad; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 0 AND article_suffix_order = 0 AND body LIKE 'بعد الاطلاع على قانون تنظيم وتنمية استخدام التكنولوجيا المالية%' AND body LIKE '%رقم 5 لسنة 2022 ؛%' AND body LIKE '%رقم 151 لسنة 2020 ؛%' AND body LIKE '%رقم 58 لسنة 2022%' AND body LIKE '%بتاريخ 2023/6/21 ؛%' AND body LIKE '%قرر :') THEN RAISE EXCEPTION '[156] الديباجة غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 1 AND article_suffix_order = 0 AND body LIKE 'يعمل بالقواعد المرفقة فى شأن التجهيزات والبنية التكنولوجية%' AND body LIKE '%لمزاولة الأنشطة المالية غير المصرفية .') THEN RAISE EXCEPTION '[156] المادة 1 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 2 AND article_suffix_order = 0 AND body LIKE 'على الشركات والجهات الراغبة فى الحصول على ترخيص أو موافقة%' AND body LIKE '%والتى تحددها الهيئة .') THEN RAISE EXCEPTION '[156] المادة 2 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 3 AND article_suffix_order = 0 AND body LIKE 'ينشر هذا القرار فى الوقائع المصرية%' AND body LIKE '%من اليوم التالى لتاريخ نشره .%' AND body LIKE '%د . محمد فريد صالح') THEN RAISE EXCEPTION '[156] المادة 3 غير سليم'; END IF;
  IF NOT EXISTS (SELECT 1 FROM articles WHERE law_id = v_law_id AND article_no = 4 AND article_suffix_order = 0 AND body LIKE 'فى تطبيق أحكام القواعد الآتية%' AND body LIKE '%1- التجهيزات (Facilities Infrastructure) :%' AND body LIKE '%أجهزة الشبكات ونقل البيانات%وأنظمة البنية التحتية للتطبيقات%' AND body LIKE '%8- مرونة التحمل السيبرانية (Cyber Resiliency)%' AND body LIKE '%12- أنظمة التكنولوجيا الحرجة%' AND body LIKE '%20- الجهات المخاطبة :%' AND body LIKE '%رقم 5 لسنة 2022') THEN RAISE EXCEPTION '[156] أولاً - تعريفات غير سليم'; END IF;
